-- =============================================================================
-- 506 — LE CAHIER D'EXERCICES DE 2DE (partie 8)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/2de/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 506 --niveau 2de --fichiers histoire-geo.n2,histoire-geo.n3 --suffixe 8 > supabase/contenu/506_exercices_2de_8.sql
--
-- 60 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   histoire-geo.n2         30 exercices · 10 chapitres
--   histoire-geo.n3         30 exercices · 10 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('4bcb8f4e-c59a-5809-91d2-776d9e6feedb'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Qui sont les humanistes ?","competence":"lire-tableau","situation":"Zoé prépare une fiche pour son cours d’histoire : elle a dressé un tableau de cinq humanistes et de ce qu’ils ont apporté. Aide-la à le lire.","documents":[{"id":"humanistes","type":"tableau","titre":"Cinq humanistes","source":"Tableau établi d’après le cours.","colonnes":["L’humaniste","Son œuvre ou son apport"],"lignes":[["Pétrarque","Il inaugure le mouvement en Italie"],["Érasme","Un Nouveau Testament en grec"],["Thomas More","L’Utopie"],["Rabelais","Il écrit en français"],["Montaigne","Il écrit en français"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le nom de l’humaniste qui inaugure le mouvement en Italie.","aide":"Cherche la ligne qui parle de l’Italie.","type":"zone","document":"humanistes","multiple":false},{"enonce":"Combien d’humanistes de ce tableau écrivent en français ?","aide":"Relis la colonne de droite, ligne par ligne.","type":"nombre","unite":"humanistes"},{"enonce":"Que font les humanistes des textes grecs et latins de l’Antiquité ?","aide":"Le tableau cite un Nouveau Testament en grec : dans quelle langue l’ont-ils lu ?","type":"choix","options":[{"id":"a","texte":"Ils les traduisent tous en français"},{"id":"b","texte":"Ils les gardent enfermés dans les monastères"},{"id":"c","texte":"Ils les relisent dans leur langue d’origine"},{"id":"d","texte":"Ils les remplacent par des textes neufs"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c0"]},"explication":"**Pétrarque** inaugure le mouvement humaniste en Italie, avant Érasme, More, Rabelais et Montaigne."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 humanistes","explication":"**Deux** : Rabelais et Montaigne écrivent en français ; les autres s’adressent surtout aux savants de toute l’Europe."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les humanistes relisent les Anciens **dans leur langue d’origine** : c’est le retour aux textes, comme le Nouveau Testament en grec d’Érasme."}]$ex$::jsonb),
  ('4bcb8f4e-c59a-5809-91d2-776d9e6feedb'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le livre qui coûte dix fois moins","competence":"lire-graphique","situation":"Mathieu, étudiant imaginaire à Strasbourg, veut acheter un livre. Un libraire lui explique ce que Gutenberg a changé depuis Mayence, vers 1450.","documents":[{"id":"libraire","type":"texte","genre":"recit","titre":"Chez le libraire","source":"Texte écrit pour l’exercice.","blocs":["À Mayence, vers 1450, Johannes Gutenberg compose les pages avec des caractères mobiles en métal : il suffit de les assembler, de les encrer et de presser la feuille.","Le libraire de Mathieu lui montre deux exemplaires du même ouvrage : l’un a été copié à la main par un moine, l’autre est sorti d’un atelier d’imprimeur. « Voilà pourquoi tout le monde lit davantage », dit-il."]},{"id":"prix","type":"graphique","forme":"barres","titre":"Le prix d’un même livre","source":"Chiffres imaginés pour l’exercice, qui reprennent le rapport indiqué dans le cours.","categories":["Copié à la main","Imprimé"],"series":[{"nom":"Prix","valeurs":[20,2],"teinte":"violet"}],"axeY":{"titre":"Prix","unite":"en florins","min":0,"max":20,"pas":5},"valeurs":true}],"questions":[{"enonce":"Touche les mots qui désignent l’invention de Gutenberg.","aide":"Il s’agit de pièces de métal qu’on peut déplacer.","type":"zone","document":"libraire","multiple":true},{"enonce":"Combien de fois le livre imprimé est-il moins cher que le livre copié à la main ?","aide":"Divise le prix le plus élevé par le prix le plus bas.","type":"nombre","unite":"fois"},{"enonce":"Avec 20 florins, combien de livres imprimés Mathieu peut-il acheter ?","aide":"Un livre imprimé coûte 2 florins.","type":"nombre","unite":"livres"},{"enonce":"Quelle conséquence l’imprimerie a-t-elle sur la circulation des idées ?","aide":"Pense au prix et à la quantité de livres en circulation.","type":"choix","options":[{"id":"a","texte":"Une idée met désormais plus longtemps à circuler qu’avant"},{"id":"b","texte":"Une idée voyage en quelques semaines au lieu de plusieurs années"},{"id":"c","texte":"Une idée reste réservée aux savants des monastères"},{"id":"d","texte":"Une idée ne voyage plus, faute de copistes pour la recopier"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11","m12"]},"explication":"Les **caractères mobiles** en métal sont l’invention de Gutenberg : on les assemble pour composer chaque page."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 fois","explication":"20 ÷ 2 = **10** : le prix d’un livre est divisé par dix, comme le dit le cours."},{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10 livres","explication":"20 ÷ 2 = **10 livres imprimés** pour le prix d’un seul livre copié à la main."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avec des millions de volumes en cinquante ans, une idée circule en **quelques semaines, non en années** : c’est ce qui fait de l’imprimerie une révolution."}]$ex$::jsonb),
  ('4bcb8f4e-c59a-5809-91d2-776d9e6feedb'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"De Mayence à Chambord","competence":"se-reperer-temps","situation":"Léa prépare un exposé sur la Renaissance en Europe : elle veut montrer comment l’imprimerie, les guerres d’Italie et le roi de France ont fait voyager les idées. Elle a une carte et une frise.","documents":[{"id":"carte","type":"carte","titre":"Trois villes de la Renaissance","fond":"europe","frontieres":true,"cadrage":[-5,40,20,55],"source":"Carte d’après le cours ; frontières actuelles.","lieux":[{"id":"z1","lon":8.27,"lat":50,"symbole":"lettre","lettre":"A","teinte":"corail"},{"id":"z2","lieu":"florence","symbole":"lettre","lettre":"B","teinte":"corail"},{"id":"z3","lieu":"paris","symbole":"lettre","lettre":"C","teinte":"corail"}]},{"id":"frise","type":"frise","titre":"Les débuts de la Renaissance en Europe","debut":1440,"fin":1560,"pas":20,"source":"Frise établie d’après le cours.","periodes":[{"id":"z4","debut":1494,"fin":1559,"nom":"Guerres d’Italie","teinte":"ambre"}],"evenements":[{"id":"z5","date":1450,"nom":"Gutenberg"},{"id":"z6","date":1530,"nom":"Collège de France"},{"id":"z7","date":1539,"nom":"Villers-Cotterêts"}]}],"questions":[{"enonce":"Touche la ville où Gutenberg met au point l’imprimerie vers 1450.","aide":"C’est une ville d’Allemagne, au bord du Rhin.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche l’événement qui impose le français dans les actes officiels.","aide":"Cherche une ordonnance, la plus tardive des trois événements.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la fondation du Collège de France de l’ordonnance de Villers-Cotterêts ?","aide":"Soustrais les deux dates lues sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Pendant combien d’années durent les guerres d’Italie, de 1494 à 1559 ?","aide":"Soustrais la date de début à la date de fin de la période.","type":"nombre","unite":"ans"},{"enonce":"Pourquoi les guerres d’Italie changent-elles le goût des Français ?","aide":"Regarde où la période des guerres est située : B est une ville italienne.","type":"choix","options":[{"id":"a","texte":"Les Français y découvrent l’imprimerie de Gutenberg"},{"id":"b","texte":"Les Français y découvrent les palais et l’art italiens"},{"id":"c","texte":"Les Français y rencontrent Luther à Wittenberg"},{"id":"d","texte":"Les Français y apprennent à écrire en français"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Gutenberg travaille à **Mayence**, ville d’Allemagne : la lettre A. Florence (B) est le foyer de l’art italien, Paris (C) la capitale du roi."},{"cle":{"type":"zone","ids":["z7"]},"explication":"L’ordonnance de **Villers-Cotterêts**, en 1539, impose le français dans les actes officiels. Le Collège de France, lui, date de 1530."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 ans","explication":"1539 − 1530 = **9 ans**."},{"cle":{"type":"nombre","valeur":65,"tolerance":0},"affichage":"65 ans","explication":"1559 − 1494 = **65 ans** : les guerres d’Italie durent plus d’un demi-siècle."},{"cle":{"type":"choix","ids":["b"]},"explication":"En Italie, les Français découvrent **les palais et l’art italiens** : François Ier attire Léonard de Vinci et fait bâtir Chambord."}]$ex$::jsonb),
  ('e9917f09-c475-53ff-8a0a-430989127935'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Trois réformateurs, trois Églises","competence":"lire-tableau","situation":"Samir prépare une affiche pour le CDI : « Au XVIe siècle, l’unité chrétienne se brise ». Il a noté trois réformateurs, leur pays et leur date.","documents":[{"id":"refo","type":"tableau","titre":"Les trois protestantismes","source":"Tableau établi d’après le cours.","colonnes":["Réformateur","Lieu","Date","Courant né"],"lignes":[["Luther","Allemagne",1517,"Luthéranisme"],["Calvin","Genève",1536,"Calvinisme"],["Henri VIII","Angleterre",1534,"Anglicanisme"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la date de l’Acte de suprématie d’Henri VIII.","aide":"Repère la ligne d’Henri VIII, puis la colonne des dates.","type":"zone","document":"refo","multiple":false},{"enonce":"Associe chaque réformateur au courant né de son action.","aide":"Le nom du courant ressemble au nom du réformateur, sauf pour le roi d’Angleterre.","type":"association","gauche":[{"id":"g0","texte":"Luther"},{"id":"g1","texte":"Calvin"},{"id":"g2","texte":"Henri VIII"}],"droite":[{"id":"d0","texte":"Calvinisme"},{"id":"d1","texte":"Anglicanisme"},{"id":"d2","texte":"Luthéranisme"}]},{"enonce":"Combien d’années séparent le geste de Luther de la publication de Calvin ?","aide":"Soustrais la plus petite date à la plus grande dans les lignes de Luther et de Calvin.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Henri VIII rompt avec Rome en **1534** par l’Acte de suprématie, qui le met à la tête de l’Église d’Angleterre."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Luther** → luthéranisme, **Calvin** → calvinisme, **Henri VIII** → anglicanisme (l’Église d’Angleterre)."},{"cle":{"type":"nombre","valeur":19,"tolerance":0},"affichage":"19 ans","explication":"1536 − 1517 = **19 ans**."}]$ex$::jsonb),
  ('e9917f09-c475-53ff-8a0a-430989127935'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Pourquoi l’Église est-elle critiquée ?","competence":"analyser-texte","situation":"Thomas, un marchand imaginaire d’Augsbourg, écrit à son frère en 1520. Il raconte ce que beaucoup de ses voisins reprochent à l’Église, puis tu classeras les idées de la Réforme et la réponse catholique.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre de Thomas à son frère, 1520","source":"Lettre écrite pour l’exercice.","blocs":["Cher Jakob, on ne parle plus que de cela dans les auberges. Un moine vient de passer avec des indulgences : en payant, on obtient une remise de peine, et l’argent doit servir à bâtir une immense église à Rome.","Les évêques vivent dans le luxe et cumulent les bénéfices, pendant que nos curés, dont l’ignorance est bien connue, savent à peine expliquer la messe.","Mon voisin, qui lit les Écritures dans son livre imprimé, dit qu’il faut revenir aux textes eux-mêmes."]}],"questions":[{"enonce":"Touche le mot qui désigne ce que le moine vend pour financer l’église de Rome.","aide":"C’est une remise de peine qu’on obtient en payant.","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche le mot qui nomme la faiblesse reprochée aux curés.","aide":"Pense à ce que les curés savent mal faire : expliquer, enseigner.","type":"zone","document":"lettre","multiple":false},{"enonce":"Que dit le voisin de Thomas, qui lit son livre imprimé, et quel mouvement annonce-t-il ?","aide":"Pense à la manière dont les humanistes relisent les textes.","type":"choix","options":[{"id":"a","texte":"Il faut quitter l’Empire : c’est la guerre qui commence"},{"id":"b","texte":"Il faut revenir aux textes : c’est l’humanisme qui arme la critique"},{"id":"c","texte":"Il faut acheter plus d’indulgences : c’est l’Église qui parle"},{"id":"d","texte":"Il faut brûler les livres : c’est l’Inquisition qui parle"}],"multiple":false},{"enonce":"Range ces éléments : idée des protestants ou réponse des catholiques ?","aide":"Les séminaires et les jésuites viennent du concile de Trente et de la Réforme catholique.","type":"categories","categories":[{"id":"c0","texte":"Idée des protestants"},{"id":"c1","texte":"Réponse des catholiques"}],"items":[{"id":"i0","texte":"Les jésuites, fondés en 1540"},{"id":"i1","texte":"L’art baroque"},{"id":"i2","texte":"Le refus du culte des saints"},{"id":"i3","texte":"Le salut par la foi"},{"id":"i4","texte":"La création des séminaires"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m19"]},"explication":"Ce sont les **indulgences**, dont l’argent finance la reconstruction de Saint-Pierre de Rome : elles déclenchent la protestation de Luther."},{"cle":{"type":"zone","ids":["m56"]},"explication":"Thomas dénonce l’**ignorance** des curés, mal formés : c’est la faiblesse de formation que le concile de Trente corrigera avec les séminaires."},{"cle":{"type":"choix","ids":["b"]},"explication":"L’**humanisme** exige le retour aux textes et fournit à la critique ses outils."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c1"}},"explication":"Le **salut par la foi** et le refus du culte des saints sont des idées de Luther et de Calvin ; **séminaires**, **jésuites** et **art baroque** sont des réponses catholiques."}]$ex$::jsonb),
  ('e9917f09-c475-53ff-8a0a-430989127935'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"L’Europe se divise : carte et frise de la Réforme","competence":"se-reperer-espace","situation":"Inès prépare un dossier sur les guerres de Religion : elle veut comprendre où naissent les trois protestantismes, où se trouve le pape, et comment on tente de rétablir la paix.","documents":[{"id":"carte","type":"carte","titre":"Quatre villes de la Réforme","fond":"europe","frontieres":true,"cadrage":[-6,40,20,56],"source":"Carte d’après le cours ; frontières actuelles.","lieux":[{"id":"z1","lon":12.65,"lat":51.87,"symbole":"lettre","lettre":"A","teinte":"corail"},{"id":"z2","lieu":"geneve","symbole":"lettre","lettre":"B","teinte":"corail"},{"id":"z3","lieu":"londres","symbole":"lettre","lettre":"C","teinte":"corail"},{"id":"z4","lieu":"rome","symbole":"lettre","lettre":"D","teinte":"corail"}]},{"id":"frise","type":"frise","titre":"La Réforme, de 1517 à 1598","debut":1510,"fin":1600,"pas":10,"source":"Frise établie d’après le cours.","periodes":[{"id":"z5","debut":1562,"fin":1598,"nom":"Guerres de Religion","teinte":"ambre"}],"evenements":[{"id":"z6","date":1517,"nom":"Luther"},{"id":"z7","date":1534,"nom":"Acte de suprématie"},{"id":"z8","date":1545,"nom":"Concile de Trente"},{"id":"z9","date":1555,"nom":"Paix d’Augsbourg"},{"id":"z10","date":1572,"nom":"Saint-Barthélemy"},{"id":"z11","date":1598,"nom":"Édit de Nantes"}]}],"questions":[{"enonce":"Touche la ville où Calvin réforme l’Église.","aide":"C’est une ville au bord d’un lac, au pied des Alpes.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la ville du pape, au cœur de l’Église catholique.","aide":"C’est la capitale de l’Italie actuelle.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche l’événement par lequel, dans l’Empire, le prince choisit la religion de ses sujets.","aide":"Un traité de paix signé à Augsbourg, au milieu du siècle.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années durent les guerres de Religion en France ?","aide":"Soustrais la date de début à la date de fin de la période.","type":"nombre","unite":"ans"},{"enonce":"Quelle différence y a-t-il entre la paix d’Augsbourg (1555) et l’édit de Nantes (1598) ?","aide":"Augsbourg concerne les princes de l’Empire, Nantes les protestants de France.","type":"choix","options":[{"id":"a","texte":"Augsbourg met fin au concile de Trente ; Nantes en ouvre un autre"},{"id":"b","texte":"Augsbourg interdit le luthéranisme ; Nantes interdit les jésuites"},{"id":"c","texte":"Augsbourg accorde aux protestants la liberté de conscience ; Nantes laisse chaque prince choisir la religion"},{"id":"d","texte":"Augsbourg laisse le prince choisir la religion ; Nantes accorde aux protestants la liberté de conscience et des places de sûreté"}],"multiple":false}]}$ex$::jsonb,
