   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"En **1520**, excommunié par une bulle, Luther brûle le document."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 ans","explication":"1521 − 1517 = **4 ans**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Luther **refuse de se rétracter** devant Charles Quint ; mis au ban de l’Empire, il est caché à la Wartburg."}]$ex$::jsonb),
  ('2ff97d37-ecc8-548e-bb9c-6b7e7129ac98'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Ce que Luther garde et ce qu’il rejette","competence":"analyser-document","situation":"Élise, imprimeuse imaginaire à Wittenberg, raconte comment les idées de Luther voyagent. Un tableau résume ce que le réformateur conserve de l’Église catholique et ce qu’il rejette.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Dans l’atelier d’Élise, à Wittenberg","source":"Récit écrit pour l’exercice.","blocs":["Dans mon atelier, les thèses du docteur Luther contre les indulgences ont été imprimées en quelques jours, puis traduites. Des colporteurs les ont portées dans tout l’Empire.","Plus tard, pendant sa retraite à la Wartburg, Luther traduit le Nouveau Testament en allemand : désormais, chacun peut lire par lui-même."]},{"id":"tableau","type":"tableau","titre":"Dans l’Église de Luther","source":"Tableau établi d’après le cours.","colonnes":["Ce qui subsiste","Ce qui est rejeté"],"lignes":[["Le baptême","Le culte des saints"],["L’eucharistie","Le purgatoire"],["—","Le célibat des prêtres"],["—","L’autorité du pape"]]}],"questions":[{"enonce":"Touche le mot qui explique que les thèses circulent si vite.","aide":"Pense à l’invention de Gutenberg.","type":"zone","document":"recit","multiple":false},{"enonce":"Combien de sacrements Luther conserve-t-il ?","aide":"Compte les cases de la colonne « Ce qui subsiste ».","type":"nombre","unite":"sacrements"},{"enonce":"Associe chaque principe de Luther à son sens.","aide":"Le nom du principe donne un indice : une seule chose compte à chaque fois.","type":"association","gauche":[{"id":"g0","texte":"La foi seule"},{"id":"g1","texte":"L’Écriture seule"},{"id":"g2","texte":"Le sacerdoce universel"}],"droite":[{"id":"d0","texte":"La Bible fait autorité, non la tradition"},{"id":"d1","texte":"Tout croyant est prêtre"},{"id":"d2","texte":"Le salut ne s’achète ni ne se mérite par les œuvres"}]},{"enonce":"Pourquoi la traduction du Nouveau Testament en allemand est-elle si importante ?","aide":"Pense au principe de l’Écriture seule.","type":"choix","options":[{"id":"a","texte":"Seuls les prêtres peuvent désormais lire la Bible"},{"id":"b","texte":"Le pape peut mieux contrôler la lecture"},{"id":"c","texte":"Chacun peut lire par lui-même, et donc juger par lui-même"},{"id":"d","texte":"Le latin devient la seule langue de l’Église"}],"multiple":false}]}$ex$::jsonb,
