  ('ec702236-f6bb-568c-8747-da3844617b3e'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Dans les carnets de Léonard","competence":"analyser-document","situation":"Une visite scolaire au Clos Lucé, à Amboise : la guide présente les carnets de Léonard, ses milliers de pages de dessins et ce qu’on en a retenu. Tu retrouves ce qu’il observait et ce qu’il imaginait.","documents":[{"id":"guide","type":"texte","genre":"recit","titre":"Les mots de la guide","source":"Texte écrit pour l’exercice.","blocs":["Léonard a rempli des milliers de pages de dessins et de notes. Il les écrit de droite à gauche : on ne peut les lire qu’avec un miroir.","Rien n’y est décoratif : chaque dessin sert à comprendre ou à préparer une idée. Pourtant, presque aucune de ses machines n’a été construite."]},{"id":"domaines","type":"tableau","titre":"Ce que Léonard étudie","source":"Tableau établi d’après le cours.","colonnes":["Le domaine","Ce qu’il en tire"],"lignes":[["L’anatomie","Une trentaine de dissections ; le fœtus dans l’utérus"],["Le vol des oiseaux","Des projets de machine volante"],["L’eau et la lumière","Tourbillons, ombres, reflets"],["La mécanique","Char d’assaut, pont mobile, scaphandre"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui donne le moyen de lire les carnets de Léonard.","aide":"Il écrit de droite à gauche : quel objet renvoie l’image inversée ?","type":"zone","document":"guide","multiple":false},{"enonce":"Range ces éléments : Léonard observe la nature, ou il imagine une machine ?","aide":"Une dissection ou un tourbillon se regarde ; un char d’assaut se conçoit.","type":"categories","categories":[{"id":"c0","texte":"Il observe la nature"},{"id":"c1","texte":"Il imagine une machine"}],"items":[{"id":"i0","texte":"Les dissections"},{"id":"i1","texte":"Le char d’assaut"},{"id":"i2","texte":"Le scaphandre"},{"id":"i3","texte":"Les tourbillons de l’eau"},{"id":"i4","texte":"Le pont mobile"}]},{"enonce":"Que dit la guide du sort des machines dessinées par Léonard ?","aide":"Relis la dernière phrase du texte.","type":"choix","options":[{"id":"a","texte":"Aucune n’est restée dans ses carnets"},{"id":"b","texte":"La plupart ont été construites"},{"id":"c","texte":"Elles ont toutes été construites par ses élèves"},{"id":"d","texte":"Presque aucune n’a été construite"}],"multiple":false},{"enonce":"Pourquoi l’étude de l’anatomie, du vol et de la mécanique fait-elle de Léonard un idéal humaniste ?","aide":"Regarde la variété des domaines étudiés dans le tableau.","type":"choix","options":[{"id":"a","texte":"Il travaille pour un seul prince qui lui dicte ses sujets"},{"id":"b","texte":"Il refuse de peindre pour se consacrer à la mécanique"},{"id":"c","texte":"Il copie uniquement les textes des Anciens"},{"id":"d","texte":"Il unit l’art, la technique et la science dans une même curiosité"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27"]},"explication":"Léonard écrit **en miroir**, de droite à gauche : on lit mieux ses carnets avec un miroir."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c1"}},"explication":"**Dissections** et **tourbillons** sont des observations ; **char d’assaut**, **pont mobile** et **scaphandre** sont des machines qu’il imagine."},{"cle":{"type":"choix","ids":["d"]},"explication":"Ses carnets comptent des milliers de pages, mais **presque rien n’a été construit** : Léonard dessine pour comprendre."},{"cle":{"type":"choix","ids":["d"]},"explication":"Léonard unit **l’art, la technique et la science** dans une même curiosité : c’est l’idéal de l’homme humaniste."}]$ex$::jsonb),
