nnel.","type":"choix","options":[{"id":"a","texte":"Qu’il faut réunir chaque année les états généraux du royaume"},{"id":"b","texte":"Qu’il faut confier tout le gouvernement à un seul ministre"},{"id":"c","texte":"Qu’il faut quitter définitivement le royaume de France"},{"id":"d","texte":"Ne jamais laisser Paris décider ni gouverner par un ministre principal"}],"multiple":false}]}$ex$::jsonb,
