   $ex${"titre":"Les arsenaux et le canal de Colbert","competence":"lire-carte","situation":"Sous Louis XIV, Colbert fait construire des arsenaux pour la flotte et un canal pour relier deux mers. Aziz les repère sur une carte de France avant de répondre à un quiz.","documents":[{"id":"carte","type":"carte","titre":"Quatre villes du royaume de Colbert","fond":"france","cadrage":[-2.5,42,7,47],"source":"Carte d’après le cours. Le trait entre C et D figure le canal du Midi.","lieux":[{"id":"z1","lon":-0.96,"lat":45.94,"symbole":"lettre","lettre":"A","teinte":"corail"},{"id":"z2","lieu":"toulon","symbole":"lettre","lettre":"B","teinte":"corail"},{"id":"z3","lieu":"toulouse","symbole":"lettre","lettre":"C","teinte":"corail"},{"id":"z4","lieu":"sete","symbole":"lettre","lettre":"D","teinte":"corail"}],"traits":[{"id":"z5","points":["toulouse","sete"],"style":"fleche","teinte":"bleu"}]}],"questions":[{"enonce":"Touche l’arsenal de Colbert qui construit la flotte sur la façade atlantique : Rochefort.","aide":"Rochefort est sur la côte de l’océan Atlantique, à l’ouest.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche l’arsenal de Colbert situé sur la Méditerranée : Toulon.","aide":"Toulon est un port du sud-est de la France.","type":"zone","document":"carte","multiple":false},{"enonce":"Quelles mers le canal du Midi, achevé par Riquet en 1681, relie-t-il ?","aide":"Il relie Toulouse (reliée à l’océan par la Garonne) à la côte méditerranéenne.","type":"choix","options":[{"id":"a","texte":"La Méditerranée et la mer Noire"},{"id":"b","texte":"L’Atlantique et la Méditerranée"},{"id":"c","texte":"La Manche et la mer Baltique"},{"id":"d","texte":"La mer du Nord et la Manche"}],"multiple":false}]}$ex$::jsonb,
