   $ex${"titre":"Protéger les manufactures du royaume","competence":"lire-graphique","situation":"Un drapier imaginaire de Villeneuvette, Anselme, constate que sa production augmente depuis que Colbert a relevé les droits de douane. Il note deux chiffres, en milliers de pièces de tissu.","documents":[{"id":"tissu","type":"graphique","forme":"barres","titre":"Les pièces de drap de la région d’Anselme","source":"Chiffres imaginés pour l’exercice ; les tarifs douaniers sont relevés en 1664 et 1667.","categories":["1663","1670"],"series":[{"nom":"Drap importé","valeurs":[40,25],"teinte":"violet"},{"nom":"Drap des manufactures","valeurs":[10,30],"teinte":"ambre"}],"axeY":{"titre":"Pièces de drap","unite":"en milliers","min":0,"max":40,"pas":10},"valeurs":true}],"questions":[{"enonce":"Touche l’année où les manufactures produisent plus de drap que la région n’en importe.","aide":"Compare, dans chaque année, la barre importée et la barre des manufactures.","type":"zone","document":"tissu","multiple":false},{"enonce":"De combien de milliers de pièces le drap importé baisse-t-il entre 1663 et 1670 ?","aide":"Soustrais 25 à 40.","type":"nombre","unite":"milliers"},{"enonce":"Combien de fois la production des manufactures a-t-elle été multipliée entre 1663 et 1670 ?","aide":"Divise la valeur de 1670 par celle de 1663.","type":"nombre","unite":"fois"},{"enonce":"Pourquoi Colbert relève-t-il les tarifs douaniers en 1664 et 1667 ?","aide":"Regarde ce que deviennent les importations après les tarifs.","type":"choix","options":[{"id":"a","texte":"Pour protéger la production française de la concurrence étrangère"},{"id":"b","texte":"Pour aider les marchands étrangers à vendre en France"},{"id":"c","texte":"Pour faire venir plus de drap étranger"},{"id":"d","texte":"Pour faire baisser le prix du drap français"}],"multiple":false}]}$ex$::jsonb,
