  ('472ea26f-1a12-5139-a8ee-7d869d746f28'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un drapier protestant face à la révocation","competence":"analyser-document","situation":"Élie, drapier protestant imaginaire de Villeneuvette, écrit en 1686 à son cousin de Londres. Il raconte comment la politique de Colbert a fait vivre son atelier, puis pourquoi il décide de partir.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’Élie à son cousin, 1686","source":"Lettre écrite pour l’exercice.","blocs":["Cher cousin, grâce aux privilèges de la manufacture royale, mes ouvriers tissent un drap réputé jusqu’au Levant, et ses règlements très stricts garantissent sa qualité.","Mais le roi a révoqué l’édit de Nantes l’an dernier. Comme beaucoup d’artisans et de négociants protestants, je dois partir vers l’Angleterre avec mes ouvriers."]},{"id":"limites","type":"tableau","titre":"Les limites de la politique de Colbert","source":"Tableau établi d’après le cours.","colonnes":["La limite","Son effet"],"lignes":[["Les guerres de Louis XIV","Elles engloutissent les recettes"],["La fiscalité : la taille","Elle pèse sur les paysans et épargne nobles et clergé"],["La révocation de l’édit de Nantes (1685)","Des dizaines de milliers de protestants partent"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui nomme la mesure prise par le roi qui oblige Élie à partir.","aide":"C’est une décision de 1685 qui annule l’édit de Nantes.","type":"zone","document":"lettre","multiple":false},{"enonce":"En quoi le départ d’Élie et de ses ouvriers affaiblit-il la politique de Colbert ?","aide":"Pense à ce que perdent les manufactures quand leurs ouvriers s’en vont.","type":"choix","options":[{"id":"a","texte":"Les manufactures royales ferment toutes leurs portes en 1686"},{"id":"b","texte":"Ils quittent les manufactures pour s’engager dans l’armée du roi"},{"id":"c","texte":"Les protestants cessent de payer la taille aux collecteurs du roi"},{"id":"d","texte":"Des artisans qui faisaient tourner le commerce partent chez les voisins"}],"multiple":false},{"enonce":"Associe chaque limite à son effet.","aide":"Reprends le tableau.","type":"association","gauche":[{"id":"g0","texte":"Les guerres de Louis XIV"},{"id":"g1","texte":"La taille"},{"id":"g2","texte":"La révocation de l’édit de Nantes"}],"droite":[{"id":"d0","texte":"Elle pèse sur les paysans"},{"id":"d1","texte":"Le départ de nombreux artisans"},{"id":"d2","texte":"Elles engloutissent les recettes"}]},{"enonce":"Qui paie la taille, et qui en est épargné ?","aide":"Reprends la ligne de la fiscalité dans le tableau.","type":"categories","categories":[{"id":"c0","texte":"Elle pèse sur eux"},{"id":"c1","texte":"Ils en sont épargnés"}],"items":[{"id":"i0","texte":"Les paysans"},{"id":"i1","texte":"Le clergé"},{"id":"i2","texte":"Les nobles"}]},{"enonce":"Pendant combien d’années Colbert est-il contrôleur général des finances, de 1665 à 1683 ?","aide":"Soustrais 1665 à 1683.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
