  ('aeb8044a-72b1-5320-afb9-c47a697bfd6a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un marquis ruiné à Versailles","competence":"analyser-texte","situation":"Le marquis de Valcourt, personnage imaginaire, écrit à un ami resté en province. Il raconte comment la vie de cour a changé sa situation.","documents":[{"id":"journal","type":"texte","genre":"lettre","titre":"Lettre du marquis de Valcourt, vers 1690","source":"Lettre écrite pour l’exercice.","blocs":["Mon cher ami, je vis à Versailles depuis trois ans. Le roi m’a accordé une pension et une charge à la cour : j’ai l’honneur d’approcher Sa Majesté, et je ne songerais pas à le quitter.","Mon domaine me coûte cher : je l’ai laissé à mon intendant, et mon gouvernement de province n’est plus qu’un titre. Le véritable pouvoir y est exercé par l’intendant du roi, qui n’est pas noble d’épée.","Vous qui êtes resté chez vous, vous êtes peut-être plus puissant, mais ici, moi, je ne coûte plus rien au roi : je suis sous ses yeux."]}],"questions":[{"enonce":"Touche le mot qui nomme l’avantage financier que le roi accorde au marquis.","aide":"C’est une somme versée par le roi pour attacher la noblesse à la cour.","type":"zone","document":"journal","multiple":false},{"enonce":"Touche le mot qui désigne celui qui exerce le vrai pouvoir dans la province du marquis.","aide":"Il n’est pas noble d’épée ; le roi l’envoie administrer la province.","type":"zone","document":"journal","multiple":false},{"enonce":"Range ces moyens du roi : ils attachent la noblesse à la cour, ou ils lui retirent du pouvoir ?","aide":"Pensions et honneurs sont des faveurs ; intendants et gouverneurs touchent à l’administration des provinces.","type":"categories","categories":[{"id":"c0","texte":"Ils attachent la noblesse"},{"id":"c1","texte":"Ils lui retirent du pouvoir"}],"items":[{"id":"i0","texte":"L’honneur d’approcher le roi"},{"id":"i1","texte":"Les intendants"},{"id":"i2","texte":"La perte du pouvoir réel des gouverneurs"},{"id":"i3","texte":"Les pensions"}]},{"enonce":"Pourquoi, selon le cours, un noble ruiné à Versailles est-il moins dangereux qu’un noble puissant dans sa province ?","aide":"Relis ce que le marquis dit de sa pension et de son gouvernement.","type":"choix","options":[{"id":"a","texte":"Il ne sait plus manier l’épée pour lever des troupes"},{"id":"b","texte":"Il est devenu magistrat dans un parlement du royaume"},{"id":"c","texte":"Il n’a plus aucun privilège fiscal ni aucun titre de noblesse"},{"id":"d","texte":"Il dépend du roi pour vivre et n’a plus de pouvoir local"}],"multiple":false}]}$ex$::jsonb,
