   $ex${"titre":"Remontrance contre lit de justice, et les échecs de la réforme","competence":"observer-schema","situation":"Un édit du roi déplaît au parlement : une bataille de procédure commence. Plus tard, quatre ministres tentent de réformer l’impôt. Tu relis le schéma et le tableau pour comprendre pourquoi la monarchie bute sur les privilèges.","documents":[{"id":"conflit","type":"schema","titre":"Un édit du roi face au parlement","source":"Schéma simplifié d’après le cours.","largeur":340,"hauteur":330,"elements":[{"forme":"rect","x":20,"y":10,"l":190,"h":38,"arrondi":8,"teinte":"jaune","motif":"plein","texte":"Le roi publie un édit","id":"z1","zone":true},{"forme":"ligne","de":[115,48],"a":[115,82],"fleche":"fin","teinte":"violet"},{"forme":"rect","x":20,"y":82,"l":190,"h":40,"arrondi":8,"teinte":"ambre","motif":"clair","texte":"Le parlement l’examine","id":"z2","zone":true},{"forme":"ligne","de":[115,122],"a":[115,156],"fleche":"fin","teinte":"violet"},{"forme":"rect","x":20,"y":156,"l":190,"h":40,"arrondi":8,"teinte":"corail","motif":"clair","texte":"Droit de remontrance","id":"z3","zone":true},{"forme":"texte","x":220,"y":180,"texte":"critique, retarde","taille":"petit","italique":true,"ancre":"debut"},{"forme":"ligne","de":[115,196],"a":[115,230],"fleche":"fin","teinte":"violet"},{"forme":"rect","x":20,"y":230,"l":190,"h":40,"arrondi":8,"teinte":"violet","motif":"clair","texte":"Lit de justice","id":"z4","zone":true},{"forme":"texte","x":220,"y":254,"texte":"le roi impose","taille":"petit","italique":true,"ancre":"debut"},{"forme":"ligne","de":[115,270],"a":[115,292],"fleche":"fin","teinte":"violet"},{"forme":"rect","x":20,"y":292,"l":190,"h":32,"arrondi":8,"teinte":"vert","motif":"clair","texte":"Édit enregistré","id":"z5","zone":true}]},{"id":"ministres","type":"tableau","titre":"Les tentatives de réforme fiscale","source":"Tableau établi d’après le cours.","colonnes":["Le réformateur","Le sort de sa réforme"],"lignes":[["Machault d’Arnouville","Échec"],["Turgot","Échec"],["Necker","Échec"],["Calonne","Échec"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’arme dont le parlement dispose pour critiquer et retarder un édit.","aide":"C’est un droit de critiquer l’édit avant de l’enregistrer.","type":"zone","document":"conflit","multiple":false},{"enonce":"Touche la riposte du roi pour imposer l’enregistrement.","aide":"Le roi vient en personne au parlement, assis sur un siège particulier.","type":"zone","document":"conflit","multiple":false},{"enonce":"Combien de ministres du tableau ont échoué à réformer l’impôt ?","aide":"Compte les lignes du tableau.","type":"nombre","unite":"ministres"},{"enonce":"Pourquoi les réformes fiscales échouent-elles les unes après les autres ?","aide":"Pense à ceux que la réforme voudrait faire contribuer davantage.","type":"choix","options":[{"id":"a","texte":"Les ministres refusent systématiquement de lever l’impôt du roi"},{"id":"b","texte":"La monarchie ne peut pas toucher aux privilèges fiscaux sans crise"},{"id":"c","texte":"Les parlements ont été supprimés bien avant l’année 1789"},{"id":"d","texte":"Le roi interdit tout changement par principe depuis Louis XIV"}],"multiple":false},{"enonce":"Complète la conclusion du cours.","aide":"C’est la date où la monarchie absolue s’effondre.","type":"trous","segments":["Faute de pouvoir réformer l’impôt, Louis XVI convoque les ",0," en ",1,"."],"banque":["états généraux","1648","parlements","1789","1715"]}]}$ex$::jsonb,
