  ('57cb7130-74e3-5fb5-8ea6-f6c33b3a884d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Ce que le Bill of Rights interdit au roi","competence":"analyser-texte","situation":"Après la Glorieuse Révolution, le Parlement impose au nouveau roi un texte qui fixe les règles. Un élève de Londres, Ben, lit une version simplifiée en classe.","documents":[{"id":"bill","type":"texte","genre":"source","titre":"Les règles de 1689, résumées","source":"Texte adapté du Bill of Rights (1689), écrit pour l’exercice : ce n’est pas le texte original.","blocs":["Le roi ne peut pas lever d’impôt sans l’accord du Parlement.","Le roi ne peut pas entretenir d’armée permanente sans l’accord du Parlement.","Les élections au Parlement doivent être libres.","Les parlementaires sont libres de parler au Parlement.","Les sujets ont le droit d’adresser des pétitions au roi."]}],"questions":[{"enonce":"Touche le mot qui désigne ce que le roi ne peut plus lever sans le Parlement.","aide":"C’est le consentement dont dépend l’argent de l’État.","type":"zone","document":"bill","multiple":false},{"enonce":"Range ces règles : elles interdisent quelque chose au roi, ou elles garantissent une liberté ?","aide":"Les deux premières règles contiennent « sans l’accord du Parlement ».","type":"categories","categories":[{"id":"c0","texte":"Elles interdisent au roi sans le Parlement"},{"id":"c1","texte":"Elles garantissent une liberté"}],"items":[{"id":"i0","texte":"Entretenir une armée permanente"},{"id":"i1","texte":"Droit de pétition"},{"id":"i2","texte":"Parole libre des parlementaires"},{"id":"i3","texte":"Lever un impôt"},{"id":"i4","texte":"Élections libres"}]},{"enonce":"Combien de règles du texte sont des libertés garanties (et non des interdits au roi) ?","aide":"Les interdits concernent l’impôt et l’armée ; compte les autres paragraphes.","type":"nombre","unite":"règles"},{"enonce":"Quelle arme décisive permet au Parlement de limiter le roi ?","aide":"Reprends le premier paragraphe du texte.","type":"choix","options":[{"id":"a","texte":"Le choix du successeur du roi"},{"id":"b","texte":"Le droit de lever sa propre armée"},{"id":"c","texte":"Le consentement à l’impôt"},{"id":"d","texte":"Le contrôle de l’Église catholique"}],"multiple":false}]}$ex$::jsonb,
