   $ex${"titre":"Pourquoi le livre de Voltaire est-il brûlé ?","competence":"argumenter","situation":"En 1734, Voltaire publie les Lettres philosophiques après son séjour en Angleterre. Un lecteur parisien imaginaire, Armand, écrit à un ami ce qu’il en pense. Un tableau résume ce que Voltaire admire.","documents":[{"id":"lecteur","type":"texte","genre":"lettre","titre":"Lettre d’Armand à un ami, 1734","source":"Lettre écrite pour l’exercice.","blocs":["Mon cher Paul, as-tu lu le nouveau livre sur l’Angleterre ? L’auteur y admire la tolérance religieuse et la liberté du commerce, et il montre que là-bas, le roi ne peut pas « faire de mal ».","À Paris, on murmure qu’il ne parle pas de l’Angleterre, mais de nous. Les censeurs, eux, n’ont pas ri : on dit que le livre sera brûlé."]},{"id":"admire","type":"tableau","titre":"Ce que Voltaire admire, ce qu’il vise en creux","source":"Tableau établi d’après le cours.","colonnes":["Ce qu’il admire","Ce qu’il vise en creux"],"lignes":[["La tolérance religieuse","L’intolérance française"],["La liberté de commerce","Les entraves du royaume"],["La considération pour savants et négociants","Le mépris nobiliaire"],["Un roi qui ne peut « faire de mal »","L’absolutisme"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui nomme ce que Voltaire admire en matière de religion.","aide":"C’est le contraire de l’intolérance.","type":"zone","document":"lecteur","multiple":false},{"enonce":"Associe chaque chose admirée en Angleterre à ce qu’elle vise en creux en France.","aide":"Chaque éloge de l’Angleterre est une critique de la France.","type":"association","gauche":[{"id":"g0","texte":"La tolérance religieuse"},{"id":"g1","texte":"La liberté de commerce"},{"id":"g2","texte":"Un roi qui ne peut « faire de mal »"}],"droite":[{"id":"d0","texte":"L’absolutisme"},{"id":"d1","texte":"L’intolérance française"},{"id":"d2","texte":"Les entraves du royaume"}]},{"enonce":"Voltaire est exilé en Angleterre de 1726 à 1728 et publie son livre en 1734. Combien d’années se passent entre son départ d’Angleterre et la publication ?","aide":"Soustrais 1728 à 1734.","type":"nombre","unite":"ans"},{"enonce":"Pourquoi les Lettres philosophiques sont-elles condamnées et brûlées en France ?","aide":"Relis le tableau : qui visent les critiques « en creux » ?","type":"choix","options":[{"id":"a","texte":"Le livre défend l’absolutisme du roi de France contre Londres"},{"id":"b","texte":"Le livre est écrit en anglais, langue que personne ne lit"},{"id":"c","texte":"Le livre est jugé beaucoup trop cher pour les lecteurs"},{"id":"d","texte":"La comparaison avec l’Angleterre est vécue comme une attaque"}],"multiple":false},{"enonce":"Complète la phrase sur Locke.","aide":"Le gouvernement naît d’un contrat et peut être renversé s’il viole ces droits.","type":"trous","segments":["Pour Locke, l’État ne crée pas les ",0," naturels, il les ",1,"."],"banque":["protège","impôts","supprime","lois","droits"]}]}$ex$::jsonb,
