   $ex${"titre":"De la taxe sur le timbre à l’indépendance","competence":"se-reperer-temps","situation":"Dylan, élève de seconde, prépare une frise sur la naissance des États-Unis : il y a placé quatre événements entre 1765 et 1781.","documents":[{"id":"frise","type":"frise","titre":"La naissance des États-Unis","debut":1760,"fin":1790,"pas":5,"source":"Frise établie d’après le cours.","evenements":[{"id":"z1","date":1765,"nom":"Stamp Act"},{"id":"z2","date":1773,"nom":"Boston Tea Party"},{"id":"z3","date":1776,"nom":"Indépendance"},{"id":"z4","date":1781,"nom":"Yorktown"}]}],"questions":[{"enonce":"Touche l’événement où les colons jettent du thé à la mer pour protester contre une taxe.","aide":"Il se situe entre le Stamp Act et la Déclaration d’indépendance.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la Boston Tea Party de la Déclaration d’indépendance ?","aide":"Soustrais 1773 à 1776.","type":"nombre","unite":"ans"},{"enonce":"Quel slogan résume la revendication des colons américains ?","aide":"Les colons n’ont aucun député à Westminster.","type":"choix","options":[{"id":"a","texte":"Pas de thé sans taxe pour les marchands"},{"id":"b","texte":"Pas d’impôt sans accord de la noblesse"},{"id":"c","texte":"Pas de taxation sans représentation"},{"id":"d","texte":"Pas de roi sans parlement des colonies"}],"multiple":false}]}$ex$::jsonb,
