  ('8c3588f5-9360-5fc9-9624-7d473e4e61aa'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La lettre d’un colon de Boston","competence":"analyser-texte","situation":"Samuel, un marchand imaginaire de Boston, écrit en 1765 à un cousin resté à Londres. Un tableau rappelle les taxes imposées par Londres aux colonies.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre de Samuel à son cousin, 1765","source":"Lettre écrite pour l’exercice.","blocs":["Cher cousin, nous sommes sujets du roi comme vous, et nous nous sentons anglais : nos assemblées sont élues et notre presse est libre.","Mais Londres veut désormais nous faire payer une taxe sur le timbre. Nous n’avons aucun député à Westminster pour en discuter : nous ne demandons pas l’indépendance, seulement d’être traités comme des sujets britanniques."]},{"id":"taxes","type":"tableau","titre":"Les taxes britanniques","source":"Tableau établi d’après le cours.","colonnes":["La taxe","Sa date"],"lignes":[["Sugar Act",1764],["Stamp Act",1765],["Townshend Acts",1767],["Taxe sur le thé",1773]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui nomme ce que Londres impose et que Samuel conteste.","aide":"La lettre dit qu’elle porte sur le timbre.","type":"zone","document":"lettre","multiple":false},{"enonce":"Que demandent les colons en 1765 ?","aide":"Relis la fin de la lettre.","type":"choix","options":[{"id":"a","texte":"La fin de toutes les assemblées élues locales"},{"id":"b","texte":"Le retour du roi Jacques II sur le trône anglais"},{"id":"c","texte":"Être traités comme des sujets britanniques"},{"id":"d","texte":"L’indépendance immédiate de leurs treize colonies"}],"multiple":false},{"enonce":"Combien d’années séparent la première de ces taxes de la taxe sur le thé ?","aide":"Soustrais 1764 à 1773.","type":"nombre","unite":"ans"},{"enonce":"Range ces taxes de la plus ancienne à la plus récente.","aide":"Lis la colonne des dates.","type":"ordre","items":[{"id":"a","texte":"Sugar Act"},{"id":"b","texte":"Stamp Act"},{"id":"c","texte":"Taxe sur le thé"},{"id":"d","texte":"Townshend Acts"}]}]}$ex$::jsonb,
