  ('4801649d-0d33-547a-b35c-c7b7211b029a'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois expériences devant l’Académie","competence":"analyser-document","situation":"En 1672, à Paris, un savant imaginaire présente ses expériences devant l’Académie royale des sciences. Une élève de seconde doit retrouver ce que chaque instrument permet de découvrir.","documents":[{"id":"seance","type":"texte","genre":"article","titre":"Compte rendu d’une séance","source":"Texte écrit pour l’exercice : le savant et la séance sont imaginaires.","blocs":["Paris, 1672. Étienne Aubry, savant imaginaire, présente trois expériences devant l’Académie royale des sciences.","Première expérience : sous une cloche de verre, il fait le vide avec une pompe. La flamme d’une bougie s’éteint et le son d’une clochette s’affaiblit.","Deuxième expérience : grâce à un microscope, il montre dans une goutte d’eau de mare de minuscules êtres vivants, invisibles à l’œil nu.","Troisième expérience : un baromètre relevé chaque jour montre que la pression de l’air change avec le temps qu’il fait.","Étienne refait chaque expérience trois fois devant les témoins : le résultat est chaque fois le même."]}],"questions":[{"enonce":"Touche l’instrument qui révèle le monde de l’infiniment petit.","aide":"Cherche l’instrument qui fait voir ce qui est invisible à l’œil nu.","type":"zone","document":"seance","multiple":false},{"enonce":"Touche l’instrument qui permet de mesurer la pression de l’air.","aide":"Il est relevé chaque jour dans la troisième expérience.","type":"zone","document":"seance","multiple":false},{"enonce":"Associe chaque instrument à ce qu’il révèle.","aide":"Le télescope n’est pas dans le texte : pense à Galilée et aux satellites de Jupiter.","type":"association","gauche":[{"id":"g0","texte":"Pompe à vide"},{"id":"g1","texte":"Microscope"},{"id":"g2","texte":"Télescope"},{"id":"g3","texte":"Baromètre"}],"droite":[{"id":"d0","texte":"L’infiniment petit"},{"id":"d1","texte":"Le vide"},{"id":"d2","texte":"La pression de l’air"},{"id":"d3","texte":"Le ciel lointain"}]},{"enonce":"Pourquoi Étienne refait-il chaque expérience devant des témoins ?","aide":"Pense à la méthode : une découverte doit pouvoir être vérifiée par d’autres.","type":"choix","options":[{"id":"a","texte":"Pour donner plus de spectacle aux académiciens présents"},{"id":"b","texte":"Pour corriger ce qu’écrivaient autrefois les auteurs anciens"},{"id":"c","texte":"Pour obtenir l’accord du roi avant de publier ses notes"},{"id":"d","texte":"Pour prouver que le résultat se reproduit et se contrôle"}],"multiple":false}]}$ex$::jsonb,
