  ('4801649d-0d33-547a-b35c-c7b7211b029a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Deux carnets, deux chemins vers la vérité","competence":"analyser-texte","situation":"Un professeur de philosophie remet à ses élèves deux pages de carnets de savants imaginaires, puis une phrase célèbre. Il veut qu’ils reconnaissent la méthode de Bacon et celle de Descartes.","documents":[{"id":"carnets","type":"texte","genre":"recit","titre":"Deux carnets de savants","source":"Textes écrits pour l’exercice : Jeanne et Hugo sont des personnages imaginaires.","blocs":["Carnet de Jeanne, naturaliste : « Pendant dix ans, j’ai noté chaque jour une mesure de la température et de la pluie. De ces centaines de relevés, je tire peu à peu une règle sur les saisons. »","Carnet de Hugo, mathématicien : « Je commence par douter de tout ce que je crois savoir. Je ne garde que ce qui est parfaitement clair, puis j’en tire pas à pas le reste, comme dans une démonstration. »"]},{"id":"phrase","type":"texte","genre":"source","titre":"Une phrase célèbre","auteur":"René Descartes, Discours de la méthode, 1637, quatrième partie","blocs":["« Je pense, donc je suis. »"]}],"questions":[{"enonce":"Quelle démarche suit Jeanne dans son carnet ?","aide":"Regarde d’où elle part : de l’expérience, ou d’une idée ?","type":"choix","options":[{"id":"a","texte":"La révélation : elle attend qu’une vérité lui soit donnée"},{"id":"b","texte":"La déduction : elle part d’une idée claire et en tire le reste"},{"id":"c","texte":"L’induction : elle part de relevés pour en tirer une règle"},{"id":"d","texte":"Le respect des Anciens : elle recopie ce qu’ils ont écrit"}],"multiple":false},{"enonce":"Touche le mot qui montre que Hugo applique le doute méthodique.","aide":"Cherche le verbe par lequel il commence.","type":"zone","document":"carnets","multiple":false},{"enonce":"Range chaque démarche chez le bon philosophe.","aide":"Bacon part de l’expérience ; Descartes part du doute et raisonne.","type":"categories","categories":[{"id":"c0","texte":"Bacon"},{"id":"c1","texte":"Descartes"}],"items":[{"id":"i0","texte":"Raisonner pas à pas, comme en mathématiques"},{"id":"i1","texte":"Partir de nombreuses expériences pour en tirer une règle"},{"id":"i2","texte":"Douter de tout pour ne garder que ce qui est évident"},{"id":"i3","texte":"Faire de l’expérience le point de départ de la science"}]},{"enonce":"Pourquoi Descartes peut-il écrire « Je pense, donc je suis » après avoir douté de tout ?","aide":"Douter, c’est déjà penser.","type":"choix","options":[{"id":"a","texte":"Même en doutant de tout, il ne peut pas douter qu’il pense"},{"id":"b","texte":"Parce qu’une expérience de laboratoire vient de le prouver"},{"id":"c","texte":"Parce que le doute lui est interdit par le roi de France"},{"id":"d","texte":"Parce que les Anciens avaient déjà prouvé son existence"}],"multiple":false},{"enonce":"Complète le résumé de la démarche scientifique nouvelle.","aide":"Trois mots du cours : deux pour Descartes, un pour Bacon.","type":"trous","segments":["Descartes fonde la science sur le doute ",0," et la ",1," ; Bacon sur l’",2," à partir de l’expérience."],"banque":["induction","méthodique","déduction","tradition","autorité"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"Jeanne part de **mesures** pour en tirer une règle : c’est l’**induction**, la démarche de Francis Bacon."},{"cle":{"type":"zone","ids":["m43"]},"explication":"Hugo commence par « **douter** » de tout : c’est le point de départ de la méthode de Descartes."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0"}},"explication":"**Bacon** : induction à partir de l’expérience. **Descartes** : doute méthodique, puis déduction à la manière des mathématiques."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le doute lui-même est une pensée : c’est la première certitude, celle sur laquelle **Descartes** reconstruit toute la connaissance."},{"cle":{"type":"trous","trous":[["methodique"],["deduction"],["induction"]]},"affichage":"méthodique · déduction · induction","explication":"Descartes : doute **méthodique** et **déduction** ; Bacon : **induction** à partir de l’expérience."}]$ex$::jsonb),
