   $ex${"titre":"Du bois au coke : la fonte change de combustible","competence":"lire-graphique","situation":"Dans une région minière imaginaire, un maître de forges compare, d’un demi-siècle à l’autre, la fonte produite au charbon de bois et celle produite au coke. Une frise l’aide à situer les machines à vapeur.","documents":[{"id":"fonte","type":"graphique","forme":"barres","titre":"Fonte produite dans la région","source":"Chiffres imaginés pour l’exercice.","categories":["1700","1740","1780","1800"],"series":[{"nom":"Charbon de bois","valeurs":[20,18,12,5],"teinte":"brun"},{"nom":"Coke","valeurs":[0,6,40,150],"teinte":"violet"}],"axeY":{"titre":"Fonte produite","unite":"en milliers de tonnes","min":0,"max":160,"pas":20},"axeX":{"titre":"Année"},"valeurs":false},{"id":"machines","type":"frise","titre":"Deux machines à vapeur","source":"Dates du cours.","debut":1700,"fin":1780,"pas":10,"evenements":[{"id":"z1","date":1712,"nom":"Newcomen"},{"id":"z2","date":1769,"nom":"Watt"}]}],"questions":[{"enonce":"Touche la première année où la fonte au coke dépasse celle au charbon de bois.","aide":"Compare les deux barres de chaque année, en commençant par 1700.","type":"zone","document":"fonte","multiple":false},{"enonce":"Quelle quantité de fonte la région produit-elle au total en 1780, coke et charbon de bois réunis ?","aide":"Additionne les deux barres de 1780.","type":"nombre","unite":"mille tonnes"},{"enonce":"Combien d’années séparent la machine de Newcomen de celle de Watt ?","aide":"Lis les deux dates sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Pourquoi le coke, tiré du charbon, remplace-t-il peu à peu le bois ?","aide":"Regarde l’évolution des deux barres : le coke progresse parce qu’il est avantageux.","type":"choix","options":[{"id":"a","texte":"Il donne une fonte de qualité et bon marché"},{"id":"b","texte":"Il se trouve dans les forêts situées près des forges"},{"id":"c","texte":"Il est réservé aux seuls maîtres de forges nobles"},{"id":"d","texte":"Il brûle sans jamais avoir besoin de fourneau"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"En **1780**, la fonte au coke (40) dépasse enfin celle au charbon de bois (12). En 1740, elle ne valait encore que 6."},{"cle":{"type":"nombre","valeur":52,"tolerance":0},"affichage":"52 mille tonnes","explication":"40 + 12 = **52 milliers de tonnes**."},{"cle":{"type":"nombre","valeur":57,"tolerance":0},"affichage":"57 ans","explication":"1769 − 1712 = **57 ans** : la machine de Newcomen épuise l’eau des mines, celle de Watt, plus efficace, fait tout tourner."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le coke de Darby (1709) donne une **fonte de qualité, à bas prix**, avec un charbon abondant : la forge n’est plus limitée par la ressource en bois."}]$ex$::jsonb),
  ('87232a97-974d-5150-9f90-b8bf0aba8175'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Manchester, 1780 : la lettre d’un manufacturier","competence":"analyser-document","situation":"Un manufacturier imaginaire écrit à son frère pour décrire sa nouvelle fabrique de coton. Son récit fait apparaître à la fois la nouveauté du travail et les conditions qui rendent l’industrie possible en Angleterre.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un manufacturier à son frère","source":"Texte écrit pour l’exercice : le manufacturier est imaginaire.","blocs":["Mon cher frère, ma fabrique compte vingt métiers. Les ouvriers arrivent à cinq heures ; la cloche règle les pauses et un contremaître surveille chaque poste.","Chacun ne fait plus qu’une seule tâche, toujours la même, du matin au soir.","La machine à vapeur tourne toute l’année, même quand la rivière est gelée. Le coton arrive de nos colonies par bateau et les toiles repartent vers les marchés lointains. Mon banquier de Londres a avancé l’argent des machines."]},{"id":"cadre","type":"tableau","titre":"Les atouts de l’Angleterre au XVIIIe siècle","source":"Tableau établi d’après le cours.","colonnes":["Atout","Ce qu’il apporte"],"lignes":[["Empire colonial","Débouchés et matières premières"],["Marine marchande","Le transport"],["Banques et Bourse de Londres","Le capital"],["Brevets","La protection de l’inventeur"],["Canaux et routes","La circulation intérieure"]],"enteteLignes":true}],"questions":[{"enonce":"Touche tous les mots qui montrent la discipline imposée dans la fabrique.","aide":"Cherche une cloche, un surveillant et une division du travail.","type":"zone","document":"lettre","multiple":true},{"enonce":"Touche le mot qui montre que la vapeur libère la fabrique des caprices de la nature.","aide":"Pense à une rivière prise par le froid.","type":"zone","document":"lettre","multiple":false},{"enonce":"Le manufacturier dit que son banquier de Londres a avancé l’argent des machines. Touche la ligne du tableau qui correspond à cet atout.","aide":"Cherche l’atout qui apporte le capital.","type":"zone","document":"cadre","multiple":false},{"enonce":"Associe chaque détail de la lettre à l’atout du tableau qu’il illustre.","aide":"Cherche chaque détail dans la lettre, puis le mot qui lui répond dans le tableau.","type":"association","gauche":[{"id":"g0","texte":"Le coton arrive de nos colonies"},{"id":"g1","texte":"Les toiles repartent par bateau"},{"id":"g2","texte":"Mon banquier a avancé l’argent"}],"droite":[{"id":"d0","texte":"Marine marchande"},{"id":"d1","texte":"Empire colonial"},{"id":"d2","texte":"Banques et Bourse de Londres"}]},{"enonce":"Qu’est-ce qui change le plus pour les ouvriers quand le travail passe de la maison à la fabrique ?","aide":"Relis la phrase sur la cloche et le contremaître.","type":"choix","options":[{"id":"a","texte":"Ils ne travaillent plus que quelques heures par jour"},{"id":"b","texte":"Ils n’organisent plus leur temps : les horaires leur sont imposés"},{"id":"c","texte":"Ils fabriquent désormais un produit entier de leurs mains"},{"id":"d","texte":"Ils choisissent chaque matin la tâche qu’ils préfèrent"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m15","m21","m32"]},"explication":"La **cloche**, le **contremaître** et la **tâche** unique de chacun montrent le nouveau travail : horaires imposés, surveillance et division des tâches."},{"cle":{"type":"zone","ids":["m53"]},"explication":"La machine tourne même quand la rivière est « **gelée** » : l’énergie ne dépend plus du vent, de l’eau ni du muscle."},{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Les **banques et la Bourse de Londres** fournissent le capital : c’est ce qui permet d’acheter les machines."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Le **coton colonial** relève de l’empire ; le transport des toiles de la **marine marchande** ; l’argent avancé du **capital** bancaire."},{"cle":{"type":"choix","ids":["b"]},"explication":"À la fabrique, le travail est **organisé de l’extérieur** : horaires fixes, surveillance et une tâche répétée, à l’inverse du travail à domicile."}]$ex$::jsonb),
  ('9742df00-45f9-5596-b6e1-ac2ef492ab66'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Ce que doit payer une famille paysanne","competence":"lire-tableau","situation":"Dans un village imaginaire de 1788, la famille de Jean fait ses comptes à la veille de la récolte. Il note ce qu’il doit verser au roi, à l’Église et au seigneur.","documents":[{"id":"comptes","type":"tableau","titre":"Les prélèvements annuels de la famille de Jean","source":"Montants imaginés pour l’exercice.","colonnes":["Prélèvement","Montant annuel (en livres)"],"lignes":[["Taille",30],["Dîme",24],["Gabelle",12],["Cens",8],["Banalités (four, moulin)",10],["Capitation",6]],"enteteLignes":true}],"questions":[{"enonce":"Touche le prélèvement que Jean verse à l’Église.","aide":"Un seul prélèvement du tableau est payé à l’Église.","type":"zone","document":"comptes","multiple":false},{"enonce":"Range chaque prélèvement selon celui qui le reçoit.","aide":"Le roi lève des impôts ; le seigneur, des droits féodaux.","type":"categories","categories":[{"id":"c0","texte":"Le roi"},{"id":"c1","texte":"L’Église"},{"id":"c2","texte":"Le seigneur"}],"items":[{"id":"i0","texte":"Gabelle"},{"id":"i1","texte":"Cens"},{"id":"i2","texte":"Taille"},{"id":"i3","texte":"Banalités (four, moulin)"},{"id":"i4","texte":"Capitation"},{"id":"i5","texte":"Dîme"}]},{"enonce":"Combien de livres Jean verse-t-il en tout au seigneur ?","aide":"Additionne les deux prélèvements seigneuriaux.","type":"nombre","unite":"livres"},{"enonce":"Combien de livres Jean verse-t-il en tout au roi ?","aide":"Additionne les trois impôts royaux.","type":"nombre","unite":"livres"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0"]},"explication":"La **dîme** est le prélèvement versé à l’Église."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c0","i3":"c2","i4":"c0","i5":"c1"}},"explication":"Au **roi** : taille, capitation et gabelle (sur le sel). À l’**Église** : la dîme. Au **seigneur** : le cens et les banalités."},{"cle":{"type":"nombre","valeur":18,"tolerance":0},"affichage":"18 livres","explication":"Cens et banalités : 8 + 10 = **18 livres**."},{"cle":{"type":"nombre","valeur":48,"tolerance":0},"affichage":"48 livres","explication":"Taille, gabelle et capitation : 30 + 12 + 6 = **48 livres**. C’est plus du double de ce qu’il paie au seigneur."}]$ex$::jsonb),
  ('9742df00-45f9-5596-b6e1-ac2ef492ab66'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre paysans, quatre campagnes","competence":"se-reperer-espace","situation":"Quatre paysans imaginaires décrivent leur vie. Il faut retrouver dans quelle région de la France de 1789 chacun vit, car les campagnes ne se ressemblent pas toutes.","documents":[{"id":"carte","type":"carte","titre":"Quatre régions rurales de la France de 1789","source":"Carte d’après le cours.","fond":"france","lieux":[{"id":"z1","lieu":"chartres","symbole":"lettre","lettre":"A"},{"id":"z2","lon":0.62,"lat":44.2,"symbole":"lettre","lettre":"B"},{"id":"z3","lon":-0.77,"lat":48.07,"symbole":"lettre","lettre":"C"},{"id":"z4","lieu":"briancon","symbole":"lettre","lettre":"D"}]},{"id":"voix","type":"texte","genre":"source","titre":"Quatre paysans parlent","source":"Textes écrits pour l’exercice : les quatre paysans sont imaginaires.","blocs":["Pierre, fermier : « Mon bail porte sur cent cinquante hectares de blé ; à la moisson, j’emploie des journaliers. »","Marthe, métayère : « La terre est à un propriétaire ; à la récolte, nous partageons le grain avec lui. »","Jean, éleveur : « Mes champs sont entourés de haies et mes prés nourrissent mes vaches. »","Louise, montagnarde : « Notre lopin est petit et en pente, mais il est à nous. »"]}],"questions":[{"enonce":"Les grandes fermes céréalières du Bassin parisien se trouvent par exemple en Beauce, autour de Chartres. Touche cette ville.","aide":"Chartres est au sud-ouest de Paris, dans une grande plaine.","type":"zone","document":"carte","multiple":false},{"enonce":"Marthe cultive en métayage, système dominant dans le Sud-Ouest. Touche la ville d’Agen, au bord de la Garonne.","aide":"Agen se trouve dans le sud-ouest, sur la Garonne, entre Bordeaux et Toulouse.","type":"zone","document":"carte","multiple":false},{"enonce":"Associe chaque paysan à la région où il vit.","aide":"Haies : bocage ; lopin sur la pente : petite propriété.","type":"association","gauche":[{"id":"g0","texte":"Pierre, fermier"},{"id":"g1","texte":"Marthe, métayère"},{"id":"g2","texte":"Jean, éleveur"},{"id":"g3","texte":"Louise, montagnarde"}],"droite":[{"id":"d0","texte":"Montagne"},{"id":"d1","texte":"Sud-Ouest"},{"id":"d2","texte":"Ouest"},{"id":"d3","texte":"Bassin parisien"}]},{"enonce":"Pourquoi une mauvaise récolte est-elle un drame pour toutes ces familles ?","aide":"Pense à ce que mangent ces familles toute l’année.","type":"choix","options":[{"id":"a","texte":"Leur propriétaire garde toujours la totalité du grain"},{"id":"b","texte":"Leur seigneur les oblige alors à quitter leur village"},{"id":"c","texte":"Leur subsistance dépend encore de la récolte de l’année"},{"id":"d","texte":"Leur curé interdit la vente du blé après la moisson"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La lettre **A** est Chartres, au cœur de la Beauce : ce sont de grandes fermes de céréales, comme celle de Pierre."},{"cle":{"type":"zone","ids":["z2"]},"explication":"La lettre **B** est Agen, dans le Sud-Ouest : le **métayage** y domine, le métayer partageant la récolte avec le propriétaire."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"Grandes fermes de blé : **Bassin parisien** ; métayage : **Sud-Ouest** ; haies et prés : **Ouest**, pays de bocage ; petite propriété : **montagne**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les progrès agricoles restent limités : la **subsistance dépend de la récolte de l’année**, et un mauvais été fait monter le prix du pain."}]$ex$::jsonb),
  ('9742df00-45f9-5596-b6e1-ac2ef492ab66'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"1788-1789 : du mauvais été à la Grande Peur","competence":"analyser-document","situation":"Un historien veut comprendre comment la crise des récoltes pousse les paysans à brûler les registres de leur seigneur en juillet 1789. Il croise un graphique du prix du pain et le récit d’une paroisse imaginaire.","documents":[{"id":"pain","type":"graphique","forme":"barres","titre":"Le prix de la livre de pain","source":"Chiffres imaginés pour l’exercice, d’après les ordres de grandeur du cours.","categories":["Janv. 1788","Sept. 1788","Janv. 1789","Avr. 1789","Juil. 1789"],"series":[{"nom":"Prix","valeurs":[8,9,12,13,14],"teinte":"ambre"}],"axeY":{"titre":"Prix de la livre de pain","unite":"en sous","min":0,"max":16,"pas":2},"axeX":{"titre":"Date"},"valeurs":false},{"id":"recit","type":"texte","genre":"recit","titre":"Dans une paroisse, en juillet 1789","source":"Récit écrit pour l’exercice : la paroisse est imaginaire.","blocs":["Le bruit court que des brigands approchent. Le tocsin sonne, les hommes s’arment et se rassemblent sur la place.","Dans la soirée, les paysans marchent vers le château, exigent les registres et brûlent le terrier, la liste des droits que le seigneur leur fait payer."]}],"questions":[{"enonce":"Touche la date où le pain est le plus cher.","aide":"Cherche la barre la plus haute.","type":"zone","document":"pain","multiple":false},{"enonce":"De combien de pour cent le prix du pain a-t-il augmenté entre janvier 1788 (8 sous) et juillet 1789 (14 sous) ?","aide":"Calcule d’abord la hausse en sous, puis compare-la au prix de départ.","type":"nombre","unite":"%"},{"enonce":"Touche le mot qui désigne le registre brûlé par les paysans.","aide":"C’est la liste des droits dus au seigneur.","type":"zone","document":"recit","multiple":false},{"enonce":"Range ces événements dans l’ordre chronologique.","aide":"Pars de la récolte de 1788 et termine par la nuit du 4 août.","type":"ordre","items":[{"id":"a","texte":"Mauvaises récoltes et hiver rigoureux (1788)"},{"id":"b","texte":"Flambée du prix du pain (printemps 1789)"},{"id":"c","texte":"Abolition des privilèges (nuit du 4 août 1789)"},{"id":"d","texte":"La Grande Peur dans les campagnes (juillet-août 1789)"}]},{"enonce":"Pourquoi les paysans brûlent-ils les terriers ?","aide":"Pense à ce que le registre permet au seigneur d’exiger.","type":"choix","options":[{"id":"a","texte":"Pour retrouver des titres de propriété enfouis au château"},{"id":"b","texte":"Pour prévenir un incendie des champs avant la moisson"},{"id":"c","texte":"Pour détruire la preuve écrite des droits qu’ils doivent payer"},{"id":"d","texte":"Pour rendre hommage au seigneur lors d’une cérémonie"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"En **juillet 1789**, la livre de pain atteint 14 sous : c’est le moment où la Grande Peur parcourt les campagnes."},{"cle":{"type":"nombre","valeur":75,"tolerance":0},"affichage":"75 %","explication":"La hausse est de 14 − 8 = 6 sous, soit 6 ÷ 8 = 0,75 : **+ 75 %**."},{"cle":{"type":"zone","ids":["m35"]},"explication":"Le **terrier** est le registre des droits et redevances dus au seigneur : le brûler, c’est effacer ce qu’on doit."},{"cle":{"type":"ordre","ids":["a","b","d","c"]},"explication":"D’abord les **mauvaises récoltes de 1788**, puis la **flambée du pain**, puis la **Grande Peur**, enfin la **nuit du 4 août** qui abolit les privilèges."},{"cle":{"type":"choix","ids":["c"]},"explication":"Sans terrier, le seigneur ne peut plus prouver ce qu’on lui doit : brûler le registre, c’est s’**attaquer aux droits féodaux**, que la nuit du 4 août abolira."}]$ex$::jsonb),
  ('8ee512e1-b90b-5c96-ab68-71ae8071b8a8'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Citadins et campagnards en 1789","competence":"lire-graphique","situation":"À la veille de la Révolution, la France est un pays de campagnes, mais les villes pèsent plus que leur nombre d’habitants. Pour commencer, on regarde où vivent les Français puis qui vit dans un port atlantique.","documents":[{"id":"repartition","type":"graphique","forme":"secteurs","titre":"Où vivent les Français au XVIIIe siècle ?","source":"Chiffres arrondis, d’après le cours.","categories":["Ville","Campagne"],"series":[{"nom":"Part de la population","valeurs":[20,80],"teinte":"violet"}]},{"id":"port","type":"tableau","titre":"Six habitants d’un port atlantique","source":"Personnages imaginés pour l’exercice.","colonnes":["Habitant","Métier"],"lignes":[["Anne","Armatrice"],["Louis","Compagnon charpentier"],["Sophie","Avocate"],["Mathieu","Portefaix"],["Claire","Négociante"],["Paul","Domestique"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la part de la population qui vit en ville.","aide":"La part des citadins est la plus petite des deux.","type":"zone","document":"repartition","multiple":false},{"enonce":"Sur 1 000 Français du XVIIIe siècle, combien vivent en ville ?","aide":"20 % veut dire 20 pour 100.","type":"nombre","unite":"personnes"},{"enonce":"Range chaque habitant du port dans son groupe.","aide":"La bourgeoisie vit de sa fortune et de ses compétences ; le peuple, de son salaire.","type":"categories","categories":[{"id":"c0","texte":"Bourgeoisie"},{"id":"c1","texte":"Peuple des villes"}],"items":[{"id":"i0","texte":"Louis, compagnon charpentier"},{"id":"i1","texte":"Claire, négociante"},{"id":"i2","texte":"Mathieu, portefaix"},{"id":"i3","texte":"Sophie, avocate"},{"id":"i4","texte":"Paul, domestique"},{"id":"i5","texte":"Anne, armatrice"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"Environ **20 %** des Français vivent en ville : un sur cinq."},{"cle":{"type":"nombre","valeur":200,"tolerance":0},"affichage":"200 personnes","explication":"20 % de 1 000 = **200 personnes** : les villes sont peu peuplées, mais elles concentrent richesse et information."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"**Armatrice, avocate et négociante** appartiennent à la bourgeoisie urbaine ; **compagnon, portefaix et domestique** au peuple des villes, dont le salaire dépend du prix du pain."}]$ex$::jsonb),
  ('8ee512e1-b90b-5c96-ab68-71ae8071b8a8'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Mai 1789 : le pain pèse sur le budget d’un compagnon","competence":"lire-tableau","situation":"À Paris, un compagnon imaginaire note son budget en année normale et en année de cherté. Il écrit ensuite à sa mère pour expliquer la colère qui monte dans son quartier.","documents":[{"id":"budget","type":"tableau","titre":"Budget d’un ménage de compagnons, pour 100 livres de dépenses","source":"Chiffres imaginés pour l’exercice.","colonnes":["Dépense","Année normale","Année de cherté"],"lignes":[["Pain",40,50],["Loyer",15,15],["Chauffage et lumière",10,10],["Vêtements",10,10],["Autres dépenses",25,"?"]],"enteteLignes":true},{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un compagnon à sa mère","source":"Texte écrit pour l’exercice : le compagnon est imaginaire.","blocs":["Paris, mai 1789. Chère mère, le pain est devenu si cher que je n’ai presque plus rien pour le reste.","Au marché, les femmes crient contre la cherté du pain et hier, une foule a menacé un boulanger. Je travaille autant qu’avant, mais mon salaire ne bouge pas."]}],"questions":[{"enonce":"Touche la dépense qui pèse le plus lourd en année de cherté.","aide":"Cherche le plus grand nombre de la dernière colonne.","type":"zone","document":"budget","multiple":false},{"enonce":"Le ménage dépense 100 livres en tout. Combien lui reste-t-il pour les « autres dépenses » en année de cherté ?","aide":"Soustrais du total les quatre autres postes de la colonne « Année de cherté ».","type":"nombre","unite":"livres"},{"enonce":"De combien de pour cent la dépense de pain a-t-elle augmenté entre l’année normale et l’année de cherté ?","aide":"La hausse est de 10 livres sur un point de départ de 40.","type":"nombre","unite":"%"},{"enonce":"Touche le mot qui explique la colère des femmes du marché.","aide":"Cherche un mot qui dit que le prix est trop élevé.","type":"zone","document":"lettre","multiple":false},{"enonce":"Que montrent ensemble le tableau et la lettre ?","aide":"Compare ce qui augmente et ce qui reste fixe.","type":"choix","options":[{"id":"a","texte":"Les boulangers refusent de vendre du pain aux familles pauvres"},{"id":"b","texte":"Le roi vient de fixer un nouveau prix du pain pour la ville"},{"id":"c","texte":"Les compagnons préfèrent désormais acheter du pain étranger"},{"id":"d","texte":"Un salaire fixe ne suit pas le prix du pain, et la colère monte"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"Le **pain** absorbe 50 livres sur 100 : c’est de loin la plus grosse dépense du ménage."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 livres","explication":"100 − (50 + 15 + 10 + 10) = **15 livres**, contre 25 en année normale : tout le reste est sacrifié."},{"cle":{"type":"nombre","valeur":25,"tolerance":0},"affichage":"25 %","explication":"10 ÷ 40 = 0,25 : **+ 25 %**. Et comme le salaire ne bouge pas, tout le reste du budget se réduit."},{"cle":{"type":"zone","ids":["m28"]},"explication":"La « **cherté** » du pain explique la colère : pour le peuple urbain, il représente jusqu’à la moitié du revenu."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le prix du pain monte alors que le **salaire reste le même** : le budget s’effondre et les émeutes éclatent."}]$ex$::jsonb),
  ('8ee512e1-b90b-5c96-ab68-71ae8071b8a8'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Nantes, 1788 : riche mais sans statut","competence":"analyser-document","situation":"Un armateur de Nantes, personnage imaginaire, écrit un mémoire sur sa condition. Un tableau compare sa situation à celle de trois autres habitants de la ville, pour comprendre pourquoi la bourgeoisie supporte de plus en plus mal les privilèges.","documents":[{"id":"memoire","type":"texte","genre":"lettre","titre":"Mémoire d’un armateur nantais","source":"Texte écrit pour l’exercice : l’armateur est un personnage imaginaire.","blocs":["Mon armement envoie dix navires aux colonies et ma fortune dépasse celle de bien des comtes. Pourtant, dans les cérémonies, un noble ruiné passe devant moi.","J’ai acheté un office pour mon fils : un jour, peut-être, il entrera dans la noblesse. En attendant, je paie la taille, et mon voisin, le marquis, en est exempté."]},{"id":"ordres","type":"tableau","titre":"Quatre habitants de Nantes","source":"Personnages et chiffres imaginés pour l’exercice.","colonnes":["Personnage","Ordre","Fortune (en milliers de livres)","Exempté de la taille ?"],"lignes":[["Bertrand, armateur","Tiers état",750,"Non"],["Marquis de Kervel","Noblesse",150,"Oui"],["Abbé Morin","Clergé",100,"Oui"],["Paul, compagnon charpentier","Tiers état",1,"Non"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la fortune la plus élevée du tableau.","aide":"Compare les nombres de la troisième colonne.","type":"zone","document":"ordres","multiple":false},{"enonce":"Combien de fois la fortune de Bertrand est-elle plus grande que celle du marquis de Kervel ?","aide":"Divise 750 par 150.","type":"nombre","unite":"fois"},{"enonce":"Touche le mot qui montre comment un bourgeois cherche à s’élever dans la société.","aide":"Cherche ce que l’armateur a acheté pour son fils.","type":"zone","document":"memoire","multiple":false},{"enonce":"Range chaque élément : ce que la bourgeoisie possède, ou ce qui lui manque.","aide":"Relis la ligne de l’armateur dans le tableau.","type":"categories","categories":[{"id":"c0","texte":"Elle le possède"},{"id":"c1","texte":"Il lui manque"}],"items":[{"id":"i0","texte":"Des exemptions fiscales"},{"id":"i1","texte":"Une grande fortune"},{"id":"i2","texte":"Des compétences"},{"id":"i3","texte":"Des honneurs réservés"}]},{"enonce":"Pourquoi un tel armateur supporte-t-il de plus en plus mal les privilèges ?","aide":"Compare sa fortune et son statut dans le tableau.","type":"choix","options":[{"id":"a","texte":"Sa richesse ne lui donne ni le rang ni les exemptions des nobles"},{"id":"b","texte":"Il ne trouve plus d’acheteurs pour les produits des colonies"},{"id":"c","texte":"Son métier est interdit aux membres du tiers état"},{"id":"d","texte":"Il doit désormais verser la dîme à chaque vente de navire"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c2"]},"explication":"Bertrand l’armateur possède **750 000 livres**, soit plus que le marquis, l’abbé et le compagnon réunis."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5 fois","explication":"750 ÷ 150 = **5** : l’armateur est cinq fois plus riche que le marquis."},{"cle":{"type":"zone","ids":["m30"]},"explication":"Acheter un « **office** » est l’une des voies par lesquelles certains bourgeois s’élèvent, parfois jusqu’à la noblesse."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"La bourgeoisie a la **fortune et les compétences**, mais il lui manque le **statut** : elle reste dans le tiers état, sans exemption fiscale ni honneurs."},{"cle":{"type":"choix","ids":["a"]},"explication":"Il est plus riche que le marquis, mais **reste dans le tiers état** : une société où le mérite s’arrête à la naissance finit par produire des gens qui veulent changer la règle."}]$ex$::jsonb),
  ('d9cf3639-b19c-55c6-8014-782cfe4080cf'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un séisme sur l’île de Taroa","competence":"analyser-texte","situation":"Un journal imaginaire raconte un séisme sur une île de fiction. À partir de l’article, il faut distinguer ce qui relève de l’événement naturel de ce qui relève de la société qu’il atteint.","documents":[{"id":"article","type":"texte","genre":"article","titre":"Taroa : la nuit du grand séisme","source":"Article écrit pour l’exercice : l’île de Taroa et les faits racontés sont imaginaires.","blocs":["Île de Taroa, 3 h du matin. Un séisme de magnitude 7 secoue la côte nord.","Dans la capitale, les immeubles ont été construits sans normes parasismiques : les murs fragiles s’effondrent sur des quartiers très peuplés. On compte des milliers de victimes."]}],"questions":[{"enonce":"Touche le mot qui désigne l’aléa.","aide":"L’aléa est l’événement possible, d’origine naturelle.","type":"zone","document":"article","multiple":false},{"enonce":"Touche le mot qui montre la vulnérabilité des habitants.","aide":"Cherche ce qui rend les bâtiments faciles à détruire.","type":"zone","document":"article","multiple":false},{"enonce":"Associe chaque notion à sa définition.","aide":"Le risque naît de la rencontre de deux éléments.","type":"association","gauche":[{"id":"g0","texte":"Aléa"},{"id":"g1","texte":"Vulnérabilité"},{"id":"g2","texte":"Risque"},{"id":"g3","texte":"Catastrophe"}],"droite":[{"id":"d0","texte":"La fragilité des populations et des biens"},{"id":"d1","texte":"Le croisement d’un aléa et d’une société vulnérable"},{"id":"d2","texte":"Un risque réalisé"},{"id":"d3","texte":"Un événement possible, comme un séisme"}]},{"enonce":"Le même séisme se produisait en pleine mer, loin de toute côte. Comment faudrait-il le qualifier ?","aide":"Sans société exposée, il n’y a pas de croisement.","type":"choix","options":[{"id":"a","texte":"Une catastrophe, car la magnitude est élevée"},{"id":"b","texte":"Un risque technologique, car il serait mesuré"},{"id":"c","texte":"Un aléa sans risque, puisque personne n’est touché"},{"id":"d","texte":"Un risque sanitaire, car la mer serait polluée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8"]},"explication":"Le **séisme** est l’aléa : un événement naturel possible, qui n’est pas un risque tant qu’il ne rencontre aucune société."},{"cle":{"type":"zone","ids":["m29"]},"explication":"Des murs « **fragiles** » : la vulnérabilité est la fragilité des populations et des biens exposés."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Un **aléa** rencontre une société **vulnérable** : c’est le **risque** ; quand il se réalise, c’est une **catastrophe**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Sans société qui puisse être atteinte, le séisme reste un **phénomène**, un aléa : le risque naît de la rencontre avec une société."}]$ex$::jsonb),
  ('d9cf3639-b19c-55c6-8014-782cfe4080cf'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux pays, un même séisme","competence":"lire-tableau","situation":"Un séisme de même magnitude frappe deux pays imaginaires, A et B, le même jour. Les bilans sont pourtant très différents. Un géographe compare les données pour comprendre pourquoi.","documents":[{"id":"bilan","type":"tableau","titre":"Le même séisme, deux bilans","source":"Données imaginées pour l’exercice.","colonnes":["","Pays A","Pays B"],"lignes":[["Magnitude","7,0","7,0"],["Habitants exposés","2 millions","2 millions"],["Bâtiments aux normes parasismiques","90 %","10 %"],["Morts",40,20000]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ligne qui explique le mieux l’écart des bilans.","aide":"Les lignes « Magnitude » et « Habitants exposés » sont identiques pour les deux pays.","type":"zone","document":"bilan","multiple":false},{"enonce":"Pour 2 millions d’habitants exposés, le pays B compte 20 000 morts. Combien cela fait-il de morts pour 100 000 habitants ?","aide":"2 millions, c’est 20 fois 100 000.","type":"nombre","unite":"morts"},{"enonce":"Range chaque élément : aléa ou facteur de vulnérabilité.","aide":"L’aléa est le phénomène naturel ; la vulnérabilité dépend de la société.","type":"categories","categories":[{"id":"c0","texte":"Aléa"},{"id":"c1","texte":"Vulnérabilité"}],"items":[{"id":"i0","texte":"Des secours peu nombreux"},{"id":"i1","texte":"Des quartiers pauvres très denses"},{"id":"i2","texte":"Une faille active sous la région"},{"id":"i3","texte":"Des bâtiments sans normes parasismiques"},{"id":"i4","texte":"Une magnitude de 7,0"}]},{"enonce":"Que prouve la comparaison des deux pays ?","aide":"Les deux pays subissent exactement le même aléa.","type":"choix","options":[{"id":"a","texte":"Les normes de construction n’ont aucun effet sur le nombre de victimes"},{"id":"b","texte":"Une magnitude plus élevée tue toujours un plus grand nombre de personnes"},{"id":"c","texte":"La gravité d’une catastrophe dépend de la vulnérabilité, pas du seul aléa"},{"id":"d","texte":"Les séismes sont plus violents dans les pays pauvres que dans les riches"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c0"]},"explication":"Les **bâtiments aux normes** (90 % contre 10 %) expliquent l’écart : l’aléa est le même, la vulnérabilité non."},{"cle":{"type":"nombre","valeur":1000,"tolerance":0},"affichage":"1000 morts","explication":"20 000 ÷ 20 = **1 000 morts pour 100 000 habitants** ; dans le pays A, ce serait 2."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0"}},"explication":"La **magnitude** et la **faille** relèvent de l’**aléa**. Les bâtiments fragiles, les secours rares et la forte densité relèvent de la **vulnérabilité**."},{"cle":{"type":"choix","ids":["c"]},"explication":"À aléa égal, le bilan est 500 fois plus lourd dans le pays B : la différence n’est pas géologique, elle est **sociale**."}]$ex$::jsonb),
  ('d9cf3639-b19c-55c6-8014-782cfe4080cf'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Haïti 2010, Japon 2011 : deux catastrophes comparées","competence":"analyser-document","situation":"Deux grandes catastrophes marquent le début du XXIe siècle. Un élève les situe sur une carte, retrace l’enchaînement de l’une d’elles, puis compare leurs bilans pour comprendre qui subit quoi.","documents":[{"id":"carte","type":"carte","titre":"Deux catastrophes sur la carte du monde","source":"Carte d’après le cours.","fond":"monde","cadrage":[-100,5,160,55],"lieux":[{"id":"z1","lon":-72.34,"lat":18.54,"symbole":"lettre","lettre":"A","teinte":"corail"},{"id":"z2","lon":141.03,"lat":37.42,"symbole":"lettre","lettre":"B","teinte":"corail"}]},{"id":"chaine","type":"chaine","disposition":"colonne","titre":"Japon, 11 mars 2011","source":"Chaîne établie d’après le cours.","noeuds":[{"id":"z3","texte":"Séisme en mer"},{"id":"z4","texte":"Tsunami géant"},{"id":"z5","texte":"Centrale de Fukushima touchée"},{"id":"z6","texte":"Accident nucléaire"}],"liens":[{"de":"z3","a":"z4"},{"de":"z4","a":"z5"},{"de":"z5","a":"z6"}]},{"id":"bilans","type":"tableau","titre":"Deux bilans","source":"Ordres de grandeur arrondis, d’après les estimations officielles.","colonnes":["","Haïti, 2010","Japon, 2011"],"lignes":[["Morts","plus de 200 000","environ 18 000"],["Dégâts matériels (milliards de dollars)","environ 8","plus de 200"]],"enteteLignes":true}],"questions":[{"enonce":"Le 12 janvier 2010, un séisme frappe Haïti. Touche la lettre qui désigne Port-au-Prince, sa capitale.","aide":"Haïti est une île des Caraïbes, à l’est de Cuba.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche le maillon qui relève d’un risque technologique.","aide":"Un risque technologique naît d’une activité humaine : industrie, nucléaire, transport.","type":"zone","document":"chaine","multiple":false},{"enonce":"Complète la phrase sur Fukushima.","aide":"Relis la chaîne, du séisme à l’accident.","type":"trous","segments":["À Fukushima, un aléa ",0," a déclenché un accident ",1," : c’est un risque hybride."],"banque":["naturel","sanitaire","technologique","climatique"]},{"enonce":"Que montre le tableau des bilans ?","aide":"Compare chaque ligne séparément : morts, puis dégâts.","type":"choix","options":[{"id":"a","texte":"Le Japon compte plus de morts et plus de dégâts qu’Haïti"},{"id":"b","texte":"Haïti compte bien plus de morts, le Japon bien plus de dégâts"},{"id":"c","texte":"Haïti compte plus de morts et plus de dégâts que le Japon"},{"id":"d","texte":"Les deux pays ont un bilan humain et matériel équivalent"}],"multiple":false},{"enonce":"Pourquoi le Japon, avec des dégâts bien plus élevés, compte-t-il beaucoup moins de morts ?","aide":"Pense à la vulnérabilité d’une société riche et préparée.","type":"choix","options":[{"id":"a","texte":"Sa vulnérabilité est plus faible : normes, alerte, préparation"},{"id":"b","texte":"Ses habitants vivaient presque tous loin des côtes et des failles"},{"id":"c","texte":"Son séisme était bien moins violent que celui d’Haïti en 2010"},{"id":"d","texte":"Les secours étrangers ont soigné immédiatement toutes les victimes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La lettre **A**, dans les Caraïbes, est Port-au-Prince, capitale d’Haïti. La lettre B est la centrale de Fukushima, au Japon."},{"cle":{"type":"zone","ids":["z6"]},"explication":"L’**accident nucléaire** est le risque technologique : un aléa naturel (séisme, tsunami) l’a déclenché, d’où le nom de risque **hybride**."},{"cle":{"type":"trous","trous":[["naturel"],["technologique"]]},"affichage":"naturel · technologique","explication":"Un aléa **naturel** (séisme et tsunami) a déclenché un accident **technologique** (centrale nucléaire) : c’est un risque hybride."},{"cle":{"type":"choix","ids":["b"]},"explication":"Haïti (pays du Sud) concentre les **victimes** ; le Japon (pays du Nord) concentre les **dégâts matériels** : c’est la différence entre pays du Nord et pays du Sud."},{"cle":{"type":"choix","ids":["a"]},"explication":"Un pays du Nord est plus **résilient** : normes parasismiques, alertes, secours, éducation aux risques. Il subit de lourds dégâts, mais beaucoup moins de victimes."}]$ex$::jsonb),
