   $ex${"titre":"Où se trouve la forêt amazonienne ?","competence":"lire-carte","situation":"Pour un exposé sur l’Amazonie, Maëlle repère la forêt sur une carte de l’Amérique du Sud. Elle veut savoir dans quel pays se trouve l’essentiel de la forêt.","documents":[{"id":"carte","type":"carte","titre":"La forêt amazonienne","source":"Carte d’après le cours ; contour de la forêt très simplifié.","fond":"monde","cadrage":[-85,-25,-30,15],"regionsCliquables":true,"aires":[{"contour":[[-77,1],[-72,4],[-67,6],[-62,5],[-55,5],[-51,4],[-50,0.5],[-48,-1.5],[-47,-5],[-50,-9],[-55,-10],[-60,-13],[-65,-12],[-69,-12],[-73,-10],[-76,-7],[-78,-4],[-79,-1]],"teinte":"vert","motif":"clair"}],"legende":[{"teinte":"vert","motif":"clair","texte":"Forêt amazonienne (contour simplifié)"}],"lieux":[{"id":"z1","lieu":"manaus","symbole":"lettre","lettre":"A","teinte":"corail"}]}],"questions":[{"enonce":"Environ 60 % de la forêt amazonienne se trouve dans un seul pays. Touche-le.","aide":"C’est le plus grand pays d’Amérique du Sud.","type":"zone","document":"carte","multiple":false},{"enonce":"Manaus se trouve au cœur de l’Amazonie, au bord du grand fleuve. Touche la lettre qui la désigne.","aide":"Elle est à l’intérieur de la forêt, loin de l’océan.","type":"zone","document":"carte","multiple":false},{"enonce":"La forêt amazonienne couvre environ 5,5 millions de km², dont 60 % au Brésil. Quelle surface cela représente-t-il au Brésil, en millions de km² ?","aide":"60 % de 5,5, c’est 5,5 × 0,6.","type":"nombre","unite":"millions de km²"},{"enonce":"Pourquoi la protection de l’Amazonie ne dépend-elle pas d’un seul État ?","aide":"Regarde la carte : jusqu’où s’étend la forêt ?","type":"choix","options":[{"id":"a","texte":"La forêt s’étend sur plusieurs pays, même si le Brésil en abrite l’essentiel"},{"id":"b","texte":"La forêt se situe en dehors de toutes les frontières terrestres"},{"id":"c","texte":"La forêt ne se trouve que dans les pays voisins du Brésil"},{"id":"d","texte":"Le Brésil a cédé la forêt à une organisation internationale"}],"multiple":false}]}$ex$::jsonb,
