,"teinte":"sable","motif":"plein"},{"forme":"rect","x":220,"y":177,"l":25,"h":16,"teinte":"sable","motif":"plein"},{"forme":"emoji","x":120,"y":75,"emoji":"🌳","taille":20},{"forme":"emoji","x":200,"y":100,"emoji":"🌳","taille":20},{"forme":"emoji","x":120,"y":130,"emoji":"🌳","taille":20},{"forme":"emoji","x":200,"y":158,"emoji":"🌳","taille":20}]}],"questions":[{"enonce":"Touche la première cause de la déforestation.","aide":"Cherche la barre la plus longue.","type":"zone","document":"causes","multiple":false},{"enonce":"Quelle part de la déforestation l’élevage bovin et le soja représentent-ils ensemble ?","aide":"Additionne les deux plus grandes barres.","type":"nombre","unite":"%"},{"enonce":"Touche la route principale, d’où partent toutes les autres.","aide":"C’est la ligne qui traverse toute la forêt de haut en bas.","type":"zone","document":"arete","multiple":false},{"enonce":"Combien de routes secondaires partent de la route principale ?","aide":"Compte-les de chaque côté de la route principale.","type":"nombre","unite":"routes"},{"enonce":"Pourquoi la forêt recule-t-elle le long des routes ?","aide":"Regarde ce qui apparaît au bout de chaque route secondaire.","type":"choix","options":[{"id":"a","texte":"Elles obligent les peuples autochtones à quitter leurs terres"},{"id":"b","texte":"Elles servent surtout à protéger la forêt des incendies"},{"id":"c","texte":"Elles empêchent la pluie de tomber sur les arbres voisins"},{"id":"d","texte":"Elles ouvrent la forêt aux éleveurs, aux colons et aux exploitants"}],"multiple":false}]}$ex$::jsonb,
