  ('7f9f4c6f-c662-500b-b570-3b0701cfd1fc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Qui veut quoi en Amazonie ?","competence":"analyser-document","situation":"Quatre personnages imaginaires parlent de la même forêt. Un graphique montre que la déforestation varie beaucoup selon les années : l’élève doit rapprocher ce que chacun veut de ce que la courbe laisse voir.","documents":[{"id":"voix","type":"texte","genre":"source","titre":"Quatre voix d’Amazonie","source":"Textes écrits pour l’exercice : les quatre personnages sont imaginaires.","blocs":["Carlos, grand éleveur : « Mes pâturages s’agrandissent chaque année : c’est ma richesse. »","Rita, venue du Nordeste : « Je ne possédais rien ; ici, j’ai enfin un lopin pour nourrir mes enfants. »","Davi, village autochtone : « Cette forêt est notre maison. L’État l’a reconnue, mais personne ne la protège vraiment. »","Marta, agent fédéral : « Les satellites me montrent où la forêt recule. Je dois contrôler et arbitrer entre tous. »"]},{"id":"defor","type":"graphique","forme":"barres","titre":"Déforestation annuelle en Amazonie brésilienne","source":"Ordres de grandeur arrondis, d’après la surveillance satellitaire brésilienne.","categories":["2004","2008","2012","2016","2021","2024"],"series":[{"nom":"Surface déboisée","valeurs":[28,13,5,8,13,6],"teinte":"corail"}],"axeY":{"titre":"Surface déboisée par an","unite":"en milliers de km²","min":0,"max":30,"pas":5},"axeX":{"titre":"Année"},"valeurs":false}],"questions":[{"enonce":"Associe chaque personnage à ce qu’il cherche.","aide":"Cherche ce que chacun dit vouloir ou défendre.","type":"association","gauche":[{"id":"g0","texte":"Carlos, grand éleveur"},{"id":"g1","texte":"Rita, venue du Nordeste"},{"id":"g2","texte":"Davi, village autochtone"},{"id":"g3","texte":"Marta, agent fédéral"}],"droite":[{"id":"d0","texte":"Préserver et arbitrer"},{"id":"d1","texte":"Valoriser sa terre"},{"id":"d2","texte":"Obtenir une vraie protection de ses terres"},{"id":"d3","texte":"Survivre sur un lopin"}]},{"enonce":"Touche le mot qui désigne l’outil qui rend la déforestation visible presque en temps réel.","aide":"Cherche ce qui permet de voir la forêt d’en haut.","type":"zone","document":"voix","multiple":false},{"enonce":"Touche l’année où la déforestation est la plus faible.","aide":"Cherche la barre la plus courte.","type":"zone","document":"defor","multiple":false},{"enonce":"De combien de milliers de km² la déforestation annuelle a-t-elle diminué entre 2004 et 2012 ?","aide":"Soustrais la valeur de 2012 à celle de 2004.","type":"nombre","unite":"milliers de km²"},{"enonce":"Que montre l’évolution de la déforestation entre 2012 et 2021 ?","aide":"Observe la hausse entre 2012 et 2021.","type":"choix","options":[{"id":"a","texte":"La déforestation ne peut que diminuer dès que les satellites existent"},{"id":"b","texte":"La déforestation dépend uniquement du climat de chaque année"},{"id":"c","texte":"Les résultats varient au gré des politiques fédérales : le recul n’est pas acquis"},{"id":"d","texte":"La déforestation a cessé depuis que la forêt est classée"}],"multiple":false}]}$ex$::jsonb,
