   $ex${"titre":"La banquise recule, les routes s’ouvrent","competence":"lire-graphique","situation":"Sacha prépare un exposé sur l’Arctique. Il compare la surface de la banquise d’été à quelques dates pour comprendre pourquoi deux nouvelles routes maritimes s’ouvrent peu à peu.","documents":[{"id":"banquise","type":"graphique","forme":"barres","titre":"La banquise arctique à la fin de l’été","source":"Ordres de grandeur arrondis, d’après le cours (surface minimale de septembre).","categories":["1980","2000","2010","2020"],"series":[{"nom":"Surface","valeurs":[7,6,5,4],"teinte":"ciel"}],"axeY":{"titre":"Surface de la banquise","unite":"en millions de km²","min":0,"max":8,"pas":1},"axeX":{"titre":"Année"},"valeurs":false}],"questions":[{"enonce":"Touche l’année où la banquise d’été est la plus réduite.","aide":"Cherche la barre la plus courte.","type":"zone","document":"banquise","multiple":false},{"enonce":"De combien de millions de km² la banquise d’été a-t-elle reculé entre 1980 et 2020 ?","aide":"Soustrais la valeur de 2020 à celle de 1980.","type":"nombre","unite":"millions de km²"},{"enonce":"Associe chaque route maritime au pays le long duquel elle passe.","aide":"Une route suit les côtes russes, l’autre l’archipel arctique d’Amérique du Nord.","type":"association","gauche":[{"id":"g0","texte":"Route maritime du Nord"},{"id":"g1","texte":"Passage du Nord-Ouest"}],"droite":[{"id":"d0","texte":"Le Canada"},{"id":"d1","texte":"La Russie"}]},{"enonce":"Pourquoi ces routes s’ouvrent-elles peu à peu ?","aide":"Pense au graphique que tu viens de lire.","type":"choix","options":[{"id":"a","texte":"Le Conseil de l’Arctique a supprimé toutes les frontières"},{"id":"b","texte":"Les États arctiques ont creusé des canaux dans la glace"},{"id":"c","texte":"Les navires brise-glaces sont devenus gratuits pour tous"},{"id":"d","texte":"La banquise d’été perd une large part de sa surface"}],"multiple":false}]}$ex$::jsonb,
