  ('9043c580-74d5-5c0e-816e-6ef231d7e5ff'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un armateur hésite : Suez ou route du Nord ?","competence":"analyser-document","situation":"Élise, armatrice imaginaire, doit faire passer des conteneurs d’Europe du Nord vers l’Asie orientale. Elle compare deux routes, puis lit une note de son équipe sur la route du Nord.","documents":[{"id":"routes","type":"tableau","titre":"Europe du Nord – Asie orientale","source":"Distances arrondies pour l’exercice.","colonnes":["Route","Distance"],"lignes":[["Par le canal de Suez","21 000 km"],["Par la route maritime du Nord","14 000 km"]],"enteteLignes":true},{"id":"note","type":"texte","genre":"article","titre":"Note à l’armatrice","source":"Note écrite pour l’exercice : Élise et son équipe sont imaginaires.","blocs":["La route du Nord est plus courte, mais la glace reste une contrainte : la navigation y est saisonnière, l’assurance coûte cher et il faut parfois l’aide de brise-glaces."]}],"questions":[{"enonce":"Combien de kilomètres la route maritime du Nord fait-elle gagner par rapport à Suez ?","aide":"Soustrais la distance la plus courte à la plus longue.","type":"nombre","unite":"km"},{"enonce":"Ce gain représente quelle fraction de la distance par Suez ?","aide":"Compare 7 000 km à 21 000 km.","type":"choix","options":[{"id":"a","texte":"Environ la moitié"},{"id":"b","texte":"Environ un tiers"},{"id":"c","texte":"Environ un dixième"},{"id":"d","texte":"Environ les deux tiers"}],"multiple":false},{"enonce":"Un cargo avance à 20 km/h. Combien d’heures de moins met-il par la route du Nord que par Suez ?","aide":"Calcule la durée de chaque trajet (distance ÷ vitesse), puis soustrais.","type":"nombre","unite":"h"},{"enonce":"Touche le mot qui dit que la route du Nord n’est utilisable qu’une partie de l’année.","aide":"Cherche un adjectif qui parle des saisons.","type":"zone","document":"note","multiple":false},{"enonce":"Pourquoi Élise peut-elle hésiter à choisir la route du Nord malgré son gain de temps ?","aide":"Relis la note de l’équipe.","type":"choix","options":[{"id":"a","texte":"Elle est plus longue que la route de Suez de plusieurs milliers de km"},{"id":"b","texte":"Elle ne permet pas de transporter de conteneurs sur ses cargos"},{"id":"c","texte":"Elle est saisonnière, coûteuse en assurance et en brise-glaces"},{"id":"d","texte":"Elle traverse des mers où la navigation est interdite à tous"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":7000,"tolerance":0},"affichage":"7000 km","explication":"21 000 − 14 000 = **7 000 km**."},{"cle":{"type":"choix","ids":["b"]},"explication":"7 000 ÷ 21 000 ≈ 0,33 : environ **un tiers** de moins, comme le dit le cours."},{"cle":{"type":"nombre","valeur":350,"tolerance":0},"affichage":"350 h","explication":"Suez : 21 000 ÷ 20 = 1 050 h ; route du Nord : 14 000 ÷ 20 = 700 h. Gain : 1 050 − 700 = **350 heures**, soit près de 15 jours."},{"cle":{"type":"zone","ids":["m17"]},"explication":"La navigation y est « **saisonnière** » : la glace la bloque une partie de l’année."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le gain de temps existe, mais l’usage reste **saisonnier** et **coûteux** (assurances, brise-glaces) : c’est pourquoi la route du Nord n’est pas encore une grande route commerciale."}]$ex$::jsonb),
  ('9043c580-74d5-5c0e-816e-6ef231d7e5ff'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Huit États, un Conseil, un sol qui dégèle","competence":"analyser-document","situation":"Au Conseil de l’Arctique siègent huit États. Un élève dresse la liste de leurs territoires arctiques puis étudie un mécanisme qui inquiète les scientifiques : le dégel du sol gelé.","documents":[{"id":"etats","type":"tableau","titre":"Les huit États du Conseil de l’Arctique","source":"Tableau établi d’après le cours.","colonnes":["État","Territoire arctique"],"lignes":[["Russie","Nord de la Sibérie"],["Canada","Nord du pays"],["États-Unis","Alaska"],["Danemark","Groenland"],["Norvège","Nord du pays"],["Islande","Nord de l’île"],["Suède","Laponie suédoise"],["Finlande","Laponie finlandaise"]],"enteteLignes":true},{"id":"cycle","type":"chaine","disposition":"cycle","titre":"Le dégel du pergélisol","source":"Schéma établi d’après le cours.","noeuds":[{"id":"z1","texte":"Réchauffement"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Méthane libéré"},{"id":"z4","texte":"Effet de serre renforcé"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z1"}]}],"questions":[{"enonce":"Touche l’État qui est présent en Arctique grâce au Groenland.","aide":"Le Groenland est un territoire danois.","type":"zone","document":"etats","multiple":false},{"enonce":"Range ces États : bordent-ils l’océan Arctique ?","aide":"Seuls cinq des huit États ont une côte sur l’océan Arctique.","type":"categories","categories":[{"id":"c0","texte":"Bordent l’océan Arctique"},{"id":"c1","texte":"Ne le bordent pas"}],"items":[{"id":"i0","texte":"Norvège"},{"id":"i1","texte":"Canada"},{"id":"i2","texte":"Islande"},{"id":"i3","texte":"Russie"},{"id":"i4","texte":"Danemark"},{"id":"i5","texte":"États-Unis"},{"id":"i6","texte":"Suède"},{"id":"i7","texte":"Finlande"}]},{"enonce":"Touche le maillon qui est un gaz à effet de serre libéré par le sol.","aide":"Cherche ce que libère le dégel du sol gelé.","type":"zone","document":"cycle","multiple":false},{"enonce":"Que faut-il écrire à la place du « ? » ?","aide":"Le pergélisol est un sol gelé en permanence.","type":"choix","options":[{"id":"a","texte":"Le dégel du pergélisol, ce sol gelé en permanence"},{"id":"b","texte":"La fonte de tous les glaciers de montagne du monde"},{"id":"c","texte":"Le gel de la banquise sur toute la mer de Barents"},{"id":"d","texte":"La disparition complète de la toundra en un an"}],"multiple":false},{"enonce":"Comment appelle-t-on un phénomène qui, comme ce cycle, s’auto-entretient ?","aide":"Observe que la flèche du dernier maillon revient au premier.","type":"choix","options":[{"id":"a","texte":"Un plateau continental"},{"id":"b","texte":"Un accord de partage"},{"id":"c","texte":"Une boucle de rétroaction"},{"id":"d","texte":"Une zone économique exclusive"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r3c0"]},"explication":"Le **Danemark** est un État arctique par le Groenland."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c0","i4":"c0","i5":"c0","i6":"c1","i7":"c1"}},"explication":"La **Russie, le Canada, les États-Unis, le Danemark** (par le Groenland) et la **Norvège** bordent l’océan Arctique. **Islande, Suède et Finlande** siègent aussi au Conseil, sans le border."},{"cle":{"type":"zone","ids":["z3"]},"explication":"Le **méthane** libéré par le dégel du pergélisol accélère le réchauffement."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le réchauffement fait **dégeler le pergélisol**, ce qui libère du méthane."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le méthane renforce l’effet de serre, qui réchauffe encore, qui fait dégeler davantage : c’est une **boucle de rétroaction**."}]$ex$::jsonb),
  ('2dfa078f-f914-5195-a3c6-4ec964cbcd24'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La France présente sur tous les océans","competence":"lire-carte","situation":"Margot trouve que la France ressemble à un petit pays sur la carte. Mais ses territoires d’outre-mer dessinent une tout autre géographie, dont les eaux sont immenses. Elle les repère sur un planisphère.","documents":[{"id":"carte","type":"carte","titre":"Quatre territoires français d’outre-mer","source":"Carte d’après le cours.","fond":"monde","lieux":[{"id":"z1","lieu":"kourou","symbole":"lettre","lettre":"A","teinte":"corail"},{"id":"z2","lieu":"noumea","symbole":"lettre","lettre":"B","teinte":"corail"},{"id":"z3","lieu":"saint-denis-reunion","symbole":"lettre","lettre":"C","teinte":"corail"},{"id":"z4","lieu":"papeete","symbole":"lettre","lettre":"D","teinte":"corail"}]}],"questions":[{"enonce":"La France lance ses fusées depuis Kourou, en Guyane. Touche la lettre qui la désigne.","aide":"La Guyane est située sur la côte nord-est de l’Amérique du Sud.","type":"zone","document":"carte","multiple":false},{"enonce":"La Nouvelle-Calédonie tire sa richesse minière du nickel. Touche sa capitale, Nouméa.","aide":"La Nouvelle-Calédonie se trouve dans l’océan Pacifique, à l’est de l’Australie.","type":"zone","document":"carte","multiple":false},{"enonce":"La zone économique exclusive française couvre environ 10,2 millions de km², dont 96 % viennent des outre-mer. Quelle surface revient à la métropole, en millions de km² (arrondie au dixième) ?","aide":"Calcule 4 % de 10,2, c’est-à-dire 10,2 × 0,04.","type":"nombre","unite":"millions de km²"},{"enonce":"Pourquoi la France possède-t-elle la deuxième zone économique exclusive du monde ?","aide":"Observe où se trouvent les lettres de la carte.","type":"choix","options":[{"id":"a","texte":"Sa métropole possède les plus longues côtes du monde"},{"id":"b","texte":"Elle a hérité des mers de ses voisins européens"},{"id":"c","texte":"Elle a acheté ces zones maritimes à l’ONU"},{"id":"d","texte":"Ses outre-mer sont présents dans tous les océans"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"La lettre **A** est Kourou, en Guyane : le centre spatial est un équipement stratégique."},{"cle":{"type":"zone","ids":["z2"]},"explication":"La lettre **B** est Nouméa : le **nickel** y fait la richesse du territoire."},{"cle":{"type":"nombre","valeur":0.4,"tolerance":0.05},"affichage":"0,4 millions de km²","explication":"100 − 96 = 4 % ; 10,2 × 0,04 ≈ **0,4 million de km²** : la France est le deuxième pays du monde par sa ZEE grâce à ses outre-mer."},{"cle":{"type":"choix","ids":["d"]},"explication":"Plus de 96 % de la ZEE vient des **outre-mer**, présents sur tous les océans : la mer fait la grandeur de la France."}]$ex$::jsonb),
  ('2dfa078f-f914-5195-a3c6-4ec964cbcd24'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un littoral qui attire, un littoral qui se dégrade","competence":"lire-graphique","situation":"La commune imaginaire de Port-Azur, sur la côte, a vu sa population et ses résidences secondaires se multiplier. Son maire compare les chiffres de l’urbanisation avant de choisir les outils de protection.","documents":[{"id":"urb","type":"graphique","forme":"barres","titre":"Surface artificialisée de Port-Azur","source":"Chiffres imaginés pour l’exercice.","categories":["1990","2000","2010","2020"],"series":[{"nom":"Surface artificialisée","valeurs":[120,150,190,240],"teinte":"gris"}],"axeY":{"titre":"Surface artificialisée","unite":"en hectares","min":0,"max":250,"pas":50},"axeX":{"titre":"Année"},"valeurs":false}],"questions":[{"enonce":"Touche la première année où la surface artificialisée dépasse 200 hectares.","aide":"Cherche la première barre qui dépasse la graduation 200.","type":"zone","document":"urb","multiple":false},{"enonce":"De combien d’hectares la surface artificialisée a-t-elle augmenté entre 1990 et 2020 ?","aide":"Soustrais la valeur de 1990 à celle de 2020.","type":"nombre","unite":"ha"},{"enonce":"De combien de pour cent la surface artificialisée a-t-elle augmenté entre 1990 et 2020 ?","aide":"Compare la hausse (120 ha) à la surface de départ (120 ha).","type":"nombre","unite":"%"},{"enonce":"Associe chaque outil de protection à son rôle.","aide":"Un seul de ces outils achète des terrains.","type":"association","gauche":[{"id":"g0","texte":"Conservatoire du littoral"},{"id":"g1","texte":"Lois Littoral et Montagne"},{"id":"g2","texte":"Natura 2000"},{"id":"g3","texte":"Parcs nationaux et marins"}],"droite":[{"id":"d0","texte":"Encadrer l’urbanisme"},{"id":"d1","texte":"Acheter des terrains pour les protéger"},{"id":"d2","texte":"Protéger des espaces à l’échelle européenne"},{"id":"d3","texte":"Classer des espaces remarquables"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k3"]},"explication":"En **2020**, la surface atteint 240 hectares ; en 2010, elle n’était que de 190."},{"cle":{"type":"nombre","valeur":120,"tolerance":0},"affichage":"120 ha","explication":"240 − 120 = **120 hectares** de plus en trente ans."},{"cle":{"type":"nombre","valeur":100,"tolerance":0},"affichage":"100 %","explication":"120 ÷ 120 = 1, soit **+ 100 %** : la surface a doublé. Un littoral attire parce qu’il est beau ; il se dégrade parce qu’il attire."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"Le **Conservatoire** achète pour soustraire au marché ; les **lois Littoral et Montagne** encadrent l’urbanisme ; **Natura 2000** agit à l’échelle européenne ; les **parcs** classent des espaces."}]$ex$::jsonb),
  ('2dfa078f-f914-5195-a3c6-4ec964cbcd24'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Valoriser et protéger : trois territoires, une mer immense","competence":"analyser-document","situation":"Un élève prépare une fiche sur les outre-mer. Il compare ce que chaque territoire valorise et ce qui le menace, puis mesure le poids de la mer dans l’espace français.","documents":[{"id":"territoires","type":"tableau","titre":"Ressources et pressions","source":"Tableau établi d’après le cours.","colonnes":["Territoire","Ressource valorisée","Pression ou pollution"],"lignes":[["Guyane","Centre spatial de Kourou, forêt","?"],["Antilles","Banane et canne à sucre","Chlordécone dans les sols"],["Nouvelle-Calédonie","Nickel et récifs","Blanchissement des coraux"]],"enteteLignes":true},{"id":"zee","type":"graphique","forme":"secteurs","titre":"La zone économique exclusive française","source":"Chiffres arrondis, d’après le cours (plus de 96 % pour les outre-mer).","categories":["Outre-mer","Métropole"],"series":[{"nom":"Part de la ZEE","valeurs":[96,4],"teinte":"turquoise"}]}],"questions":[{"enonce":"Quelle pression menace particulièrement la Guyane, à la place du « ? » ?","aide":"Elle pollue les cours d’eau au mercure.","type":"choix","options":[{"id":"a","texte":"L’orpaillage illégal"},{"id":"b","texte":"Le blanchissement des coraux"},{"id":"c","texte":"L’érosion des falaises de craie"},{"id":"d","texte":"Le chlordécone"}],"multiple":false},{"enonce":"Touche la pollution durable qui touche les sols des Antilles.","aide":"Cherche le nom d’un pesticide utilisé dans les bananeraies.","type":"zone","document":"territoires","multiple":false},{"enonce":"Touche la part de la zone économique exclusive qui revient aux outre-mer.","aide":"Cherche la part de loin la plus grande du graphique.","type":"zone","document":"zee","multiple":false},{"enonce":"Combien de fois la ZEE des outre-mer est-elle plus grande que celle de la métropole (96 % contre 4 %) ?","aide":"Divise 96 par 4.","type":"nombre","unite":"fois"},{"enonce":"Pourquoi une protection de la nature doit-elle associer les habitants du territoire ?","aide":"Pense à ce que vivent les familles qui dépendent de la pêche ou du tourisme.","type":"choix","options":[{"id":"a","texte":"La loi interdit toute activité économique dans les zones protégées"},{"id":"b","texte":"Les parcs nationaux ne peuvent être créés que par les habitants"},{"id":"c","texte":"Les habitants des outre-mer ne vivent jamais au bord de la mer"},{"id":"d","texte":"Sans projet économique local, elle est mal acceptée"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"L’**orpaillage illégal** menace la forêt guyanaise et pollue les rivières au mercure."},{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Le **chlordécone**, un pesticide utilisé dans les bananeraies, pollue durablement les sols antillais."},{"cle":{"type":"zone","ids":["k0"]},"explication":"Les **outre-mer** représentent plus de 96 % de la ZEE : la métropole n’en fournit qu’une toute petite part."},{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24 fois","explication":"96 ÷ 4 = **24** : la mer française est surtout ultramarine, donc exposée à ses risques (cyclones, coraux, pollutions)."},{"cle":{"type":"choix","ids":["d"]},"explication":"La protection réussit quand elle est **aussi un projet économique local** : sinon, elle est perçue comme une contrainte et contournée."}]$ex$::jsonb),
  ('d4c7ac00-ce2a-5f8d-b206-1d5fa66043ee'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les trois âges de la population","competence":"lire-graphique","situation":"Un manuel de géographie résume l’histoire démographique d’un pays en deux courbes : la natalité et la mortalité. Léo les lit phase après phase pour comprendre pourquoi la population explose puis se stabilise.","documents":[{"id":"transition","type":"graphique","forme":"courbe","titre":"La transition démographique","source":"Courbes schématiques imaginées pour l’exercice.","categories":["Régime ancien","Début de transition","Fin de transition","Régime moderne"],"series":[{"nom":"Natalité","valeurs":[40,38,25,12],"teinte":"violet"},{"nom":"Mortalité","valeurs":[38,18,10,10],"teinte":"corail"}],"axeY":{"titre":"Taux","unite":"pour 1 000 habitants","min":0,"max":45,"pas":5},"axeX":{"titre":"Phase"}}],"questions":[{"enonce":"Touche la phase où l’écart entre natalité et mortalité est le plus grand.","aide":"Compare l’écart entre les deux courbes à chaque phase.","type":"zone","document":"transition","multiple":false},{"enonce":"Quel est l’accroissement naturel au début de la transition, en naissances de plus que de décès pour 1 000 habitants ?","aide":"L’accroissement naturel est l’écart entre natalité et mortalité.","type":"nombre","unite":"pour 1 000"},{"enonce":"Lequel des deux indicateurs baisse en premier pendant la transition ?","aide":"Regarde laquelle des deux courbes chute entre la première et la deuxième phase.","type":"choix","options":[{"id":"a","texte":"Les deux, exactement au même moment"},{"id":"b","texte":"Aucun des deux ne baisse avant le régime moderne"},{"id":"c","texte":"La natalité"},{"id":"d","texte":"La mortalité"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k1"]},"explication":"Au début de la transition, 38 − 18 = **20** : la mortalité a chuté, la natalité reste forte, la population explose."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 pour 1 000","explication":"38 − 18 = **20 pour 1 000** : chaque année, 20 habitants de plus pour 1 000."},{"cle":{"type":"choix","ids":["d"]},"explication":"La **mortalité** chute d’abord (progrès de la santé et de l’alimentation) ; la natalité baisse plus tard : voilà pourquoi la population explose."}]$ex$::jsonb),
  ('d4c7ac00-ce2a-5f8d-b206-1d5fa66043ee'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Deux pays, deux pyramides, deux défis","competence":"lire-graphique","situation":"Deux pays imaginaires, A et B, ont à peu près le même nombre d’habitants mais pas la même structure d’âges. Une élève compare leurs répartitions par âge et leur fécondité pour comprendre les défis de chacun.","documents":[{"id":"ages","type":"graphique","forme":"barres","titre":"Répartition de la population par âge","source":"Chiffres imaginés pour l’exercice.","categories":["0-14 ans","15-64 ans","65 ans et plus"],"series":[{"nom":"Pays A","valeurs":[43,54,3],"teinte":"turquoise"},{"nom":"Pays B","valeurs":[16,56,28],"teinte":"ambre"}],"axeY":{"titre":"Part de la population","unite":"en %","min":0,"max":60,"pas":10},"axeX":{"titre":"Tranche d’âge"}},{"id":"fecondite","type":"tableau","titre":"Indice de fécondité","source":"Chiffres imaginés pour l’exercice. Seuil de renouvellement des générations : 2,1 enfants par femme.","colonnes":["Pays","Enfants par femme"],"lignes":[["Pays A",5.5],["Pays B",1.4]],"enteteLignes":true}],"questions":[{"enonce":"Touche la tranche d’âge où les deux pays se ressemblent le plus.","aide":"Compare les deux barres pour chaque tranche d’âge.","type":"zone","document":"ages","multiple":false},{"enonce":"Dans le pays B, combien y a-t-il d’actifs (15-64 ans) pour une personne de 65 ans et plus ?","aide":"Divise la part des 15-64 ans par celle des 65 ans et plus.","type":"nombre","unite":"actifs"},{"enonce":"De combien l’indice de fécondité du pays A dépasse-t-il le seuil de renouvellement des générations ?","aide":"Soustrais 2,1 à l’indice du pays A.","type":"nombre","unite":"enfants/femme"},{"enonce":"Range chaque défi dans le pays qui le rencontre.","aide":"Le pays A est très jeune, le pays B vieillit.","type":"categories","categories":[{"id":"c0","texte":"Pays A"},{"id":"c1","texte":"Pays B"}],"items":[{"id":"i0","texte":"Financer les retraites et la santé"},{"id":"i1","texte":"Compenser une pénurie de main-d’œuvre"},{"id":"i2","texte":"Créer des millions d’emplois"},{"id":"i3","texte":"Développer les métiers du grand âge"},{"id":"i4","texte":"Scolariser une jeunesse très nombreuse"},{"id":"i5","texte":"Nourrir une population qui croît vite"}]},{"enonce":"Que risque le pays B, dont la fécondité est inférieure au seuil de renouvellement ?","aide":"Compare 1,4 enfant par femme au seuil de renouvellement.","type":"choix","options":[{"id":"a","texte":"Une stabilité parfaite, avec autant de naissances que de décès"},{"id":"b","texte":"Un vieillissement et, à terme, un possible déclin de sa population"},{"id":"c","texte":"Un retour au régime démographique ancien"},{"id":"d","texte":"Une explosion de sa population et un excès de jeunes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k1"]},"explication":"Les 15-64 ans pèsent 54 % et 56 % : c’est la tranche où les deux pays diffèrent le moins."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2 actifs","explication":"56 ÷ 28 = **2** : deux actifs seulement pour une personne âgée, ce qui pèse sur le financement des retraites et de la santé."},{"cle":{"type":"nombre","valeur":3.4,"tolerance":0.05},"affichage":"3,4 enfants/femme","explication":"5,5 − 2,1 = **3,4 enfants par femme** : la population du pays A va continuer de croître vite."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0","i5":"c0"}},"explication":"Le pays **A**, très jeune, doit nourrir, scolariser et employer. Le pays **B**, vieillissant, doit financer retraites et santé, soigner la dépendance et compenser la pénurie de main-d’œuvre."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avec **1,4 enfant par femme**, moins que le seuil de 2,1, les générations ne se remplacent plus : la population **vieillit** et peut décliner sans immigration."}]$ex$::jsonb),
  ('d4c7ac00-ce2a-5f8d-b206-1d5fa66043ee'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une ville qui compte ses jeunes, un hôpital qui compte ses âgés","competence":"analyser-document","situation":"Deux responsables imaginaires parlent de leur quotidien, l’une dans une ville d’Afrique subsaharienne, l’autre dans un hôpital de Corée du Sud. Un graphique montre ce que cachent leurs témoignages : la fécondité de plusieurs pays.","documents":[{"id":"voix","type":"texte","genre":"source","titre":"Deux responsables parlent","source":"Textes écrits pour l’exercice : Adama et Mme Yoon sont des personnages imaginaires.","blocs":["Adama, maire d’une ville imaginaire d’Afrique subsaharienne : « Chaque année, des milliers de jeunes de plus arrivent à l’école, puis sur le marché du travail. Il me faut des classes, des enseignants et des emplois. »","Mme Yoon, directrice d’un hôpital imaginaire en Corée du Sud : « Mes patients sont de plus en plus âgés. Il faut financer leurs soins et trouver des soignants. »"]},{"id":"fec","type":"graphique","forme":"barres","titre":"Indice de fécondité","source":"Ordres de grandeur arrondis, vers 2022. Seuil de renouvellement : 2,1.","categories":["Niger","Nigeria","France","Japon","Corée du Sud"],"series":[{"nom":"Enfants par femme","valeurs":[6.7,5.2,1.8,1.3,0.8],"teinte":"violet"}],"axeY":{"titre":"Enfants par femme","unite":"en moyenne","min":0,"max":8,"pas":1},"axeX":{"titre":"Pays"},"valeurs":false}],"questions":[{"enonce":"Touche tous les pays dont la fécondité est sous le seuil de renouvellement des générations (2,1 enfants par femme).","aide":"Cherche les barres qui n’atteignent pas la graduation 2.","type":"zone","document":"fec","multiple":true},{"enonce":"De combien l’indice de fécondité du Niger dépasse-t-il le seuil de 2,1 enfants par femme ?","aide":"Soustrais 2,1 à 6,7.","type":"nombre","unite":"enfants/femme"},{"enonce":"Touche le mot qui montre que l’hôpital de Mme Yoon fait face au vieillissement.","aide":"Cherche l’adjectif qui parle de l’âge des patients.","type":"zone","document":"voix","multiple":false},{"enonce":"Quel avantage le pays d’Adama peut-il tirer de sa jeunesse nombreuse ?","aide":"Pense à ce qu’il faut faire des jeunes pour que leur nombre devienne un atout.","type":"choix","options":[{"id":"a","texte":"Un déclin rapide de sa population, grâce à la baisse de la fécondité"},{"id":"b","texte":"Un dividende démographique automatique, sans écoles ni emplois"},{"id":"c","texte":"Un coût réduit des retraites, car la population ne vieillit jamais"},{"id":"d","texte":"Un dividende démographique, si la jeunesse est formée et employée"}],"multiple":false},{"enonce":"Complète la phrase.","aide":"Le mot désigne l’arrivée de travailleurs venus d’autres pays.","type":"trous","segments":["Pour faire face à la pénurie de main-d’œuvre, la Corée du Sud peut accueillir des travailleurs étrangers : c’est l’",0,"."],"banque":["natalité","émigration","immigration","dépendance"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2","k3","k4"]},"explication":"La **France** (1,8), le **Japon** (1,3) et la **Corée du Sud** (0,8) sont sous le seuil de 2,1 : ils sont en situation post-transitionnelle."},{"cle":{"type":"nombre","valeur":4.6,"tolerance":0.05},"affichage":"4,6 enfants/femme","explication":"6,7 − 2,1 = **4,6 enfants par femme** : la population nigérienne est très jeune et croît rapidement."},{"cle":{"type":"zone","ids":["m55"]},"explication":"Ses patients sont « **âgés** » : la Corée du Sud est un pays post-transitionnel au vieillissement rapide."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le **dividende démographique** n’est possible que si la jeunesse est **bien formée et employée** ; sinon, il reste le chômage, l’informalité ou les migrations."},{"cle":{"type":"trous","trous":[["immigration"]]},"affichage":"immigration","explication":"L’**immigration** est l’une des réponses au vieillissement, avec l’allongement de la vie active et l’automatisation."}]$ex$::jsonb)
) AS v (chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu, cles);

INSERT INTO public.exercices (id, chapter_id, position, etoiles, gemmes, xp, nb_questions, contenu)
SELECT s.id, s.chapter_id, s.position, s.etoiles, s.gemmes, s.xp, s.nb_questions, s.contenu
FROM exercices_seed s
JOIN public.chapters c ON c.id = s.chapter_id
ON CONFLICT (id) DO UPDATE
  SET etoiles      = EXCLUDED.etoiles,
      nb_questions = EXCLUDED.nb_questions,
      contenu      = EXCLUDED.contenu,
      updated_at   = now();

INSERT INTO public.exercices_cles (exercice_id, cles)
SELECT s.id, s.cles
FROM exercices_seed s
JOIN public.exercices e ON e.id = s.id
ON CONFLICT (exercice_id) DO UPDATE SET cles = EXCLUDED.cles;

-- Contrôle : combien d'exercices de ce fichier sont en base, et combien sautés.
DO $$
DECLARE
  v_attendus INTEGER;
  v_poses    INTEGER;
BEGIN
  SELECT count(*) INTO v_attendus FROM exercices_seed;
  SELECT count(*) INTO v_poses FROM public.exercices e JOIN exercices_seed s ON s.id = e.id;
  RAISE NOTICE 'Cahier 2de (8) : % exercices posés sur % (les autres n''ont pas leur chapitre en base).', v_poses, v_attendus;
  DROP TABLE IF EXISTS pg_temp.exercices_seed;
END $$;
